def _modifier_already_baked_or_applied(
    primitive: ShapePrimitive,
    modifier: dict[str, Any],
    modifier_name: str = "",
) -> bool:
    return bool(
        primitive.primitive_type in {"deform_mesh", "boolean_mesh", "profile_mesh"}
        or primitive.primitive_type in _v2_modifier_intrinsic_primitive_types(modifier_name)
        or (
            modifier_name == "v2_polybevel_modifier"
            and primitive.primitive_type not in _SEMANTIC_MESH_BACKED_PRIMITIVE_TYPES
            and primitive.primitive_type not in {"heightfield", "terrain_patch"}
        )
        or modifier.get("geometry_applied")
        or modifier.get("baked_to_mesh")
        or modifier.get("kernel_program")
        or modifier.get("result_face_count")
    )


def _direct_modifier_source_box_record(primitive: ShapePrimitive) -> dict[str, Any] | None:
    if primitive.primitive_type not in {"box", "subdivision_box"} or primitive.extents is None:
        return None
    try:
        extents = tuple(float(value) for value in primitive.extents)
        center = tuple(float(value) for value in primitive.center)
    except (TypeError, ValueError):
        return None
    if len(extents) != 3 or len(center) != 3 or any(value <= 0.0 for value in extents):
        return None
    return {
        "primitive_type": "box",
        "source_primitive_type": primitive.primitive_type,
        "part": primitive.part or "body",
        "center": center,
        "extents": extents,
        "tags": [str(tag) for tag in primitive.tags if str(tag)],
        "blend_mode": primitive.blend_mode or "union",
        "rounding": 0.0,
    }


def _direct_modifier_source_mesh_record(
    primitive: ShapePrimitive,
    mesh: trimesh.Trimesh,
) -> dict[str, Any] | None:
    try:
        vertices = np.asarray(mesh.vertices, dtype=np.float64)
        faces = np.asarray(mesh.faces, dtype=np.int64)
    except (TypeError, ValueError):
        return None
    if vertices.ndim != 2 or vertices.shape[1] != 3 or faces.ndim != 2 or faces.shape[1] != 3:
        return None
    if len(vertices) == 0 or len(faces) == 0:
        return None
    return {
        "primitive_type": "sdf_mesh",
        "part": primitive.part or "body",
        "center": (0.0, 0.0, 0.0),
        "mesh_vertices": vertices.tolist(),
        "mesh_faces": faces.tolist(),
        "tags": [str(tag) for tag in primitive.tags if str(tag)],
        "blend_mode": primitive.blend_mode or "union",
    }


def _modifier_axis_value(
    modifier: dict[str, Any],
    keys: tuple[str, ...],
    default: str,
) -> str:
    for key in keys:
        value = modifier.get(key)
        if isinstance(value, str):
            axis = value.strip().lower()
            if axis in {"x", "y", "z"}:
                return axis
    return default


def _modifier_side_value(modifier: dict[str, Any], default: str = "positive") -> str:
    for key in ("side", "open_side", "target_side"):
        value = modifier.get(key)
        if isinstance(value, str):
            side = value.strip().lower()
            if side in {"positive", "negative"}:
                return side
    sign = _deform_modifier_float(modifier, ("normal_sign", "side_sign"), None)
    if sign is not None:
        return "positive" if sign >= 0.0 else "negative"
    return default


def _modifier_center_value(
    modifier: dict[str, Any],
    primitive: ShapePrimitive,
) -> tuple[float, float, float]:
    for key in ("center", "center_cm", "target_center", "target_center_cm", "placed_point_cm", "point_cm"):
        value = modifier.get(key)
        center = _modifier_vector3(value, (math.nan, math.nan, math.nan))
        if all(math.isfinite(item) for item in center):
            return center
    return tuple(float(value) for value in primitive.center)


def _modifier_positive_float(
    modifier: dict[str, Any],
    keys: tuple[str, ...],
    default: float | None = None,
) -> float | None:
    value = _deform_modifier_float(modifier, keys, default)
    if value is None or not math.isfinite(float(value)) or float(value) <= 0.0:
        return None
    return float(value)


def _modifier_nonnegative_float(
    modifier: dict[str, Any],
    keys: tuple[str, ...],
    default: float = 0.0,
) -> float:
    value = _deform_modifier_float(modifier, keys, default)
    if value is None or not math.isfinite(float(value)):
        return max(float(default), 0.0)
    return max(float(value), 0.0)


