def _merge_direct_modifier_mesh_metadata(
    source: trimesh.Trimesh,
    result: trimesh.Trimesh,
    *,
    name: str,
    details: dict[str, Any],
) -> trimesh.Trimesh:
    source_metadata = dict(getattr(source, "metadata", {}) or {})
    result_metadata = dict(getattr(result, "metadata", {}) or {})
    stored_details = {"modifier_name": name, **dict(details)}
    result.metadata = {
        **source_metadata,
        **result_metadata,
        _v2_direct_modifier_metadata_key(name): stored_details,
    }
    return result


def _direct_v2_inset_modifier_mesh(
    primitive: ShapePrimitive,
    mesh: trimesh.Trimesh,
    *,
    name: str,
    modifier: dict[str, Any],
    has_prior_applications: bool = False,
) -> tuple[trimesh.Trimesh, dict[str, Any]]:
    if has_prior_applications:
        return mesh, {
            "operation": "op.inset",
            "geometry_application": "direct_source_replacement_blocked_after_prior_modifier",
            "failure_reason": (
                "direct v2_inset_modifier would replace prior modifier geometry; "
                "apply it before attachments or use a baked boolean_mesh source"
            ),
        }
    kernel_program_failure = ""
    try:
        from .geometry import resolve_geometry_kernel

        geometry_kernel = resolve_geometry_kernel(None)
        records = _direct_construction_lowering_records(
            name,
            modifier,
            primitive,
            source_mesh=mesh,
            geometry_kernel=geometry_kernel,
        )
        feature_mesh, child_primitives, blend_modes, combine_details = _mesh_from_lowered_records(records)
        details = {
            "operation": "op.inset",
            "geometry_application": "kernel_program_inset_lowering",
            "geometry_applied": True,
            "kernel_program_inset_lowering_attempted": True,
            "kernel_program_inset_lowering_failed": "",
            "lowered_record_count": len(records),
            "lowered_primitive_types": [child.primitive_type for child in child_primitives],
            "lowered_blend_modes": blend_modes,
            "direct_modifier": _metadata_safe_value(modifier),
            "source_face_count": int(len(mesh.faces)),
            "source_vertex_count": int(len(mesh.vertices)),
            "result_face_count": int(len(feature_mesh.faces)),
            "result_vertex_count": int(len(feature_mesh.vertices)),
            "result_watertight": bool(feature_mesh.is_watertight),
            "result_body_count": _mesh_body_count(feature_mesh),
            **combine_details,
        }
        return _merge_direct_modifier_mesh_metadata(mesh, feature_mesh, name=name, details=details), details
    except (TypeError, ValueError, RuntimeError, AttributeError, ImportError, KeyError, OSError, ContractViolation) as exc:
        kernel_program_failure = f"{type(exc).__name__}: {exc}"
    kernel_details = {
        "kernel_program_inset_lowering_attempted": True,
        "kernel_program_inset_lowering_failed": kernel_program_failure,
    }
    source = _direct_modifier_source_box_record(primitive)
    if source is None:
        return mesh, {
            "operation": "op.inset",
            "geometry_application": "unsupported_direct_modifier_source",
            **kernel_details,
            "failure_reason": "direct v2_inset_modifier requires an axis-aligned box source",
        }
    depth = _modifier_positive_float(modifier, ("depth_cm", "depth"))
    if depth is None:
        return mesh, {
            "operation": "op.inset",
            "geometry_application": "invalid_direct_modifier_parameters",
            **kernel_details,
            "failure_reason": "v2_inset_modifier requires positive depth_cm",
        }
    normal_axis = _modifier_axis_value(modifier, ("normal_axis", "axis"), "z")
    side = _modifier_side_value(modifier)
    margin = _modifier_nonnegative_float(modifier, ("margin_cm", "edge_margin_cm", "margin"), 0.35)
    bevel_width = _modifier_nonnegative_float(
        modifier,
        ("bevel_width_cm", "rim_bevel_cm", "width_cm"),
        0.0,
    )
    polybevel = getattr(primitive, "v2_polybevel_modifier", None)
    if isinstance(polybevel, dict):
        bevel_width = max(bevel_width, _modifier_nonnegative_float(polybevel, ("width_cm", "width"), 0.0))
    line_axis = None
    if any(key in modifier for key in ("line_axis", "length_axis")):
        line_axis = _modifier_axis_value(modifier, ("line_axis", "length_axis"), _tangent_axis_pair(normal_axis)[0])
    length = _modifier_positive_float(modifier, ("length_cm", "opening_length_cm", "length"), None)
    width = _modifier_positive_float(modifier, ("opening_width_cm", "panel_width_cm", "width"), None)
    center = _modifier_center_value(modifier, primitive)
    try:
        from .asset_quality.shape_ir_v2 import _source_box_axis_inset_recess_mesh

        result, exact_modifier, failure = _source_box_axis_inset_recess_mesh(
            source,
            depth=depth,
            normal_axis=normal_axis,
            side=side,
            margin=margin,
            bevel_width=bevel_width,
            method="exact_solids_direct_v2_inset_recess_mesh_v1",
            center=center if line_axis is not None and length is not None and width is not None else None,
            line_axis=line_axis,
            length=length,
            width=width,
        )
    except (TypeError, ValueError, RuntimeError, AttributeError, ImportError, OSError) as exc:
        result, exact_modifier, failure = None, None, f"{type(exc).__name__}: {exc}"
    if result is None or exact_modifier is None:
        return mesh, {
            "operation": "op.inset",
            "geometry_application": "direct_inset_recess_failed",
            **kernel_details,
            "failure_reason": failure or "inset recess mesh unavailable",
        }
    details = {
        "operation": "op.inset",
        "geometry_application": "direct_inset_recess_mesh",
        "geometry_applied": True,
        "normal_axis": normal_axis,
        "side": side,
        "depth_cm": depth,
        "margin_cm": margin,
        "bevel_width_cm": bevel_width,
        **kernel_details,
        "direct_modifier": _metadata_safe_value(modifier),
        "exact_modifier": _metadata_safe_value(exact_modifier),
        "result_face_count": int(len(result.faces)),
        "result_vertex_count": int(len(result.vertices)),
        "result_watertight": bool(result.is_watertight),
    }
    return _merge_direct_modifier_mesh_metadata(mesh, result, name=name, details=details), details


