def _direct_socket_profile_points(
    primitive: ShapePrimitive,
    modifier: dict[str, Any],
    *,
    normal_axis: str,
    socket_shape: str,
    width: float,
    height: float,
) -> tuple[tuple[float, float], ...] | None:
    tangent_a, tangent_b = _tangent_axis_pair(normal_axis)
    center = _modifier_center_value(modifier, primitive)
    u_index = _axis_index_for_name(tangent_a)
    v_index = _axis_index_for_name(tangent_b)
    center_uv = (float(center[u_index]), float(center[v_index]))
    if socket_shape in {"cylinder", "round", "circular"}:
        radius = _modifier_positive_float(modifier, ("radius_cm", "radius", "clearance_cm", "clearance"))
        if radius is None:
            radius = min(width, height) * 0.5
        return tuple(_circle_ring(center_uv, radius, sections=max(12, int(modifier.get("segments") or 32))))
    if socket_shape in {"rounded_slot", "capsule", "slot"}:
        slot_length = _modifier_positive_float(
            modifier,
            ("slot_length_cm", "length_cm", "length"),
            max(width, height),
        )
        slot_width = _modifier_positive_float(
            modifier,
            ("slot_width_cm", "width_cm", "width"),
            min(width, height),
        )
        if slot_length is None or slot_width is None or slot_length < slot_width:
            return None
        rotation_degrees = _deform_modifier_float(modifier, ("rotation_degrees",), 0.0) or 0.0
        local = _rounded_slot_profile_polygon(
            length=slot_length,
            width=slot_width,
            segments=max(3, int(modifier.get("segments") or modifier.get("sections") or 12)),
            rotation_degrees=float(rotation_degrees),
        )
        return tuple((center_uv[0] + u, center_uv[1] + v) for u, v in local)
    return None


def _direct_v2_socket_modifier_mesh(
    primitive: ShapePrimitive,
    mesh: trimesh.Trimesh,
    *,
    name: str,
    modifier: dict[str, Any],
    has_prior_applications: bool = False,
) -> tuple[trimesh.Trimesh, dict[str, Any]]:
    if has_prior_applications:
        return mesh, {
            "operation": "op.socket",
            "geometry_application": "direct_source_replacement_blocked_after_prior_modifier",
            "failure_reason": (
                "direct v2_socket_modifier would replace prior modifier geometry; "
                "apply it before attachments or use a baked boolean_mesh source"
            ),
        }
    kernel_program_failure = ""
    try:
        from .geometry import resolve_geometry_kernel

        geometry_kernel = resolve_geometry_kernel(None)
        records = _direct_construction_lowering_records(
            name,
            modifier,
            primitive,
            source_mesh=mesh,
            geometry_kernel=geometry_kernel,
        )
        feature_mesh, child_primitives, blend_modes, combine_details = _mesh_from_lowered_records(records)
        details = {
            "operation": "op.socket",
            "geometry_application": "kernel_program_socket_lowering",
            "geometry_applied": True,
            "kernel_program_socket_lowering_attempted": True,
            "kernel_program_socket_lowering_failed": "",
            "lowered_record_count": len(records),
            "lowered_primitive_types": [child.primitive_type for child in child_primitives],
            "lowered_blend_modes": blend_modes,
            "direct_modifier": _metadata_safe_value(modifier),
            "source_face_count": int(len(mesh.faces)),
            "source_vertex_count": int(len(mesh.vertices)),
            "result_face_count": int(len(feature_mesh.faces)),
            "result_vertex_count": int(len(feature_mesh.vertices)),
            "result_watertight": bool(feature_mesh.is_watertight),
            "result_body_count": _mesh_body_count(feature_mesh),
            **combine_details,
        }
        return _merge_direct_modifier_mesh_metadata(mesh, feature_mesh, name=name, details=details), details
    except (TypeError, ValueError, RuntimeError, AttributeError, ImportError, KeyError, OSError, ContractViolation) as exc:
        kernel_program_failure = f"{type(exc).__name__}: {exc}"
    kernel_details = {
        "kernel_program_socket_lowering_attempted": True,
        "kernel_program_socket_lowering_failed": kernel_program_failure,
    }
    source = _direct_modifier_source_box_record(primitive)
    if source is None:
        return mesh, {
            "operation": "op.socket",
            "geometry_application": "unsupported_direct_modifier_source",
            **kernel_details,
            "failure_reason": "direct v2_socket_modifier requires an axis-aligned box source",
        }
    depth = _modifier_positive_float(modifier, ("depth_cm", "depth"))
    if depth is None:
        return mesh, {
            "operation": "op.socket",
            "geometry_application": "invalid_direct_modifier_parameters",
            **kernel_details,
            "failure_reason": "v2_socket_modifier requires positive depth_cm",
        }
    normal_axis = _modifier_axis_value(modifier, ("normal_axis", "axis"), "z")
    side = _modifier_side_value(modifier)
    clearance = _modifier_positive_float(modifier, ("clearance_cm", "clearance"), None)
    width = _modifier_positive_float(modifier, ("width_cm", "width"), None)
    height = _modifier_positive_float(modifier, ("height_cm", "height"), None)
    if width is None:
        width = (clearance or 0.0) * 2.0
    if height is None:
        height = (clearance or 0.0) * 2.0
    if width <= 0.0 or height <= 0.0:
        return mesh, {
            "operation": "op.socket",
            "geometry_application": "invalid_direct_modifier_parameters",
            **kernel_details,
            "failure_reason": "v2_socket_modifier requires positive width_cm/height_cm or clearance_cm",
        }
    socket_shape = str(modifier.get("socket_shape") or modifier.get("shape") or modifier.get("style") or "box").strip().lower()
    bevel_width = _modifier_nonnegative_float(modifier, ("bevel_width_cm", "rim_bevel_cm"), 0.0)
    tangent_a, tangent_b = _tangent_axis_pair(normal_axis)
    center = _modifier_center_value(modifier, primitive)
    try:
        if socket_shape in {"box", "rect", "rectangular"}:
            from .asset_quality.shape_ir_v2 import _source_box_axis_inset_recess_mesh

            result, exact_modifier, failure = _source_box_axis_inset_recess_mesh(
                source,
                depth=depth,
                normal_axis=normal_axis,
                side=side,
                margin=0.0,
                bevel_width=bevel_width,
                method="exact_solids_direct_v2_rect_socket_recess_mesh_v1",
                center=center,
                line_axis=tangent_a,
                length=width,
                width=height,
            )
        else:
            from .asset_quality.shape_ir_v2 import _source_box_axis_profile_recess_mesh

            profile_points = _direct_socket_profile_points(
                primitive,
                modifier,
                normal_axis=normal_axis,
                socket_shape=socket_shape,
                width=width,
                height=height,
            )
            if profile_points is None:
                return mesh, {
                    "operation": "op.socket",
                    "geometry_application": "invalid_direct_modifier_parameters",
                    **kernel_details,
                    "failure_reason": f"unsupported or invalid socket profile shape: {socket_shape}",
                }
            result, exact_modifier, failure = _source_box_axis_profile_recess_mesh(
                source,
                depth=depth,
                normal_axis=normal_axis,
                side=side,
                profile_points=profile_points,
                profile_u_axis=tangent_a,
                profile_v_axis=tangent_b,
                bevel_width=bevel_width,
                method=f"exact_solids_direct_v2_{socket_shape}_socket_recess_mesh_v1",
                profile_kind=f"{socket_shape}_socket",
                cutter_part=str(primitive.part or "socket"),
            )
    except (TypeError, ValueError, RuntimeError, AttributeError, ImportError, OSError) as exc:
        result, exact_modifier, failure = None, None, f"{type(exc).__name__}: {exc}"
    if result is None or exact_modifier is None:
        return mesh, {
            "operation": "op.socket",
            "geometry_application": "direct_socket_recess_failed",
            **kernel_details,
            "failure_reason": failure or "socket recess mesh unavailable",
        }
    details = {
        "operation": "op.socket",
        "geometry_application": "direct_socket_recess_mesh",
        "geometry_applied": True,
        "socket_shape": socket_shape,
        "normal_axis": normal_axis,
        "side": side,
        "width_cm": width,
        "height_cm": height,
        "depth_cm": depth,
        "bevel_width_cm": bevel_width,
        **kernel_details,
        "direct_modifier": _metadata_safe_value(modifier),
        "exact_modifier": _metadata_safe_value(exact_modifier),
        "result_face_count": int(len(result.faces)),
        "result_vertex_count": int(len(result.vertices)),
        "result_watertight": bool(result.is_watertight),
    }
    return _merge_direct_modifier_mesh_metadata(mesh, result, name=name, details=details), details


def _direct_v2_shell_modifier_mesh(
    primitive: ShapePrimitive,
    mesh: trimesh.Trimesh,
    *,
    name: str,
    modifier: dict[str, Any],
    has_prior_applications: bool = False,
) -> tuple[trimesh.Trimesh, dict[str, Any]]:
    if has_prior_applications:
        return mesh, {
            "operation": "op.shell",
            "geometry_application": "direct_source_replacement_blocked_after_prior_modifier",
            "failure_reason": (
                "direct v2_shell_modifier would reinterpret prior modifier geometry as a new shell source; "
                "apply it before attachments or use a baked shell mesh"
            ),
        }
    kernel_program_failure = ""
    try:
        from .geometry import resolve_geometry_kernel

        geometry_kernel = resolve_geometry_kernel(None)
        records = _direct_construction_lowering_records(
            name,
            modifier,
            primitive,
            source_mesh=mesh,
            geometry_kernel=geometry_kernel,
        )
        feature_mesh, child_primitives, blend_modes, combine_details = _mesh_from_lowered_records(records)
        details = {
            "operation": "op.shell",
            "geometry_application": "kernel_program_shell_lowering",
            "geometry_applied": True,
            "kernel_program_shell_lowering_attempted": True,
            "kernel_program_shell_lowering_failed": "",
            "lowered_record_count": len(records),
            "lowered_primitive_types": [child.primitive_type for child in child_primitives],
            "lowered_blend_modes": blend_modes,
            "direct_modifier": _metadata_safe_value(modifier),
            "source_face_count": int(len(mesh.faces)),
            "source_vertex_count": int(len(mesh.vertices)),
            "result_face_count": int(len(feature_mesh.faces)),
            "result_vertex_count": int(len(feature_mesh.vertices)),
            "result_watertight": bool(feature_mesh.is_watertight),
            "result_body_count": _mesh_body_count(feature_mesh),
            **combine_details,
        }
        return _merge_direct_modifier_mesh_metadata(mesh, feature_mesh, name=name, details=details), details
    except (TypeError, ValueError, RuntimeError, AttributeError, ImportError, KeyError, OSError, ContractViolation) as exc:
        kernel_program_failure = f"{type(exc).__name__}: {exc}"
    kernel_details = {
        "kernel_program_shell_lowering_attempted": True,
        "kernel_program_shell_lowering_failed": kernel_program_failure,
    }
    source = _direct_modifier_source_mesh_record(primitive, mesh)
    if source is None:
        return mesh, {
            "operation": "op.shell",
            "geometry_application": "unsupported_direct_modifier_source",
            **kernel_details,
            "failure_reason": "direct v2_shell_modifier requires a non-empty triangle mesh source",
        }
    thickness = _modifier_positive_float(modifier, ("thickness_cm", "thickness"))
    if thickness is None:
        return mesh, {
            "operation": "op.shell",
            "geometry_application": "invalid_direct_modifier_parameters",
            **kernel_details,
            "failure_reason": "v2_shell_modifier requires positive thickness_cm",
        }
    open_axis = _modifier_axis_value(modifier, ("open_axis", "axis", "normal_axis"), "z")
    open_side = _modifier_side_value(modifier)
    rim_bevel = _modifier_nonnegative_float(modifier, ("rim_bevel_cm", "bevel_width_cm"), 0.0)
    try:
        from .asset_quality.shape_ir_v2 import (
            _measured_bounds_axis_open_shell_mesh,
            _sdf_mesh_axis_open_shell,
        )

        result, exact_modifier, failure = _sdf_mesh_axis_open_shell(
            source,
            thickness=thickness,
            open_axis=open_axis,
            open_side=open_side,
            method="exact_solids_direct_v2_axis_open_shell_mesh_v1",
            rim_bevel=rim_bevel,
        )
        if result is None or exact_modifier is None:
            result, exact_modifier, measured_failure = _measured_bounds_axis_open_shell_mesh(
                source,
                thickness=thickness,
                open_axis=open_axis,
                open_side=open_side,
                method="exact_solids_direct_v2_measured_bounds_open_shell_mesh_v1",
                rim_bevel=rim_bevel,
                fallback_from="exact_solids_direct_v2_axis_open_shell_mesh_v1",
                fallback_reason=failure or "axis_open_shell_unavailable",
            )
            failure = measured_failure or failure
    except (TypeError, ValueError, RuntimeError, AttributeError, ImportError, OSError) as exc:
        result, exact_modifier, failure = None, None, f"{type(exc).__name__}: {exc}"
    if result is None or exact_modifier is None:
        return mesh, {
            "operation": "op.shell",
            "geometry_application": "direct_shell_failed",
            **kernel_details,
            "failure_reason": failure or "shell mesh unavailable",
        }
    details = {
        "operation": "op.shell",
        "geometry_application": "direct_shell_mesh",
        "geometry_applied": True,
        "thickness_cm": thickness,
        "open_axis": open_axis,
        "open_side": open_side,
        "rim_bevel_cm": rim_bevel,
        **kernel_details,
        "direct_modifier": _metadata_safe_value(modifier),
        "exact_modifier": _metadata_safe_value(exact_modifier),
        "result_face_count": int(len(result.faces)),
        "result_vertex_count": int(len(result.vertices)),
        "result_watertight": bool(result.is_watertight),
    }
    return _merge_direct_modifier_mesh_metadata(mesh, result, name=name, details=details), details


def _source_box_axis_extent(source: dict[str, Any], axis: str) -> float:
    extents = source.get("extents")
    if not isinstance(extents, (list, tuple)) or len(extents) != 3:
        return 0.0
    with suppress(TypeError, ValueError):
        return max(float(extents[_axis_index_for_name(axis)]), 0.0)
    return 0.0


def _direct_attachment_center(
    primitive: ShapePrimitive,
    source: dict[str, Any],
    modifier: dict[str, Any],
    *,
    normal_axis: str,
    normal_sign: float,
    thickness: float,
) -> tuple[float, float, float]:
    if any(
        key in modifier
        for key in ("center", "center_cm", "target_center", "target_center_cm", "placed_point_cm", "point_cm")
    ):
        return _modifier_center_value(modifier, primitive)
    center = tuple(float(value) for value in source.get("center", primitive.center))
    normal_extent = _source_box_axis_extent(source, normal_axis)
    seat_depth = _modifier_nonnegative_float(modifier, ("seat_depth_cm", "seat_depth"), 0.0)
    offset = normal_sign * (normal_extent * 0.5 + thickness * 0.5 - seat_depth)
    return _add_vec3(center, _axis_shift(normal_axis, offset))


def _direct_attachment_concat_mesh(
    source_mesh: trimesh.Trimesh,
    attachment: trimesh.Trimesh,
    *,
    name: str,
    details: dict[str, Any],
) -> trimesh.Trimesh:
    result = trimesh.util.concatenate([source_mesh, attachment])
    result.remove_infinite_values()
    result.remove_unreferenced_vertices()
    result.merge_vertices()
    with suppress(AttributeError, TypeError, ValueError, RuntimeError):
        result.fix_normals()
    source_metadata = dict(getattr(source_mesh, "metadata", {}) or {})
    attachment_metadata = dict(getattr(attachment, "metadata", {}) or {})
    details = {
        **details,
        "attachment_metadata": _metadata_safe_value(attachment_metadata),
        "result_face_count": int(len(result.faces)),
        "result_vertex_count": int(len(result.vertices)),
        "result_watertight": bool(result.is_watertight),
        "result_body_count": _mesh_body_count(result),
    }
    result.metadata = {
        **source_metadata,
        **attachment_metadata,
        _v2_direct_modifier_metadata_key(name): details,
    }
    return result


def _direct_rect_attachment_concatenated_mesh(
    primitive: ShapePrimitive,
    mesh: trimesh.Trimesh,
    *,
    name: str,
    modifier: dict[str, Any],
    center: tuple[float, float, float],
    normal_axis: str,
    normal_sign: float,
    length_axis: str,
    width_axis: str,
    length: float,
    width: float,
    thickness: float,
    component: str,
    operation: str,
) -> tuple[trimesh.Trimesh, dict[str, Any]]:
    primitive_type = "trim_band" if component == "trim_band" else "panel"
    kwargs: dict[str, Any] = {
        "primitive_type": primitive_type,
        "part": f"{primitive.part or 'body'}_{component}",
        "center": center,
        "axis": normal_axis,
        "tags": [component, "direct_v2_attachment"],
        "blend_mode": "union",
        "rounding": 0.0,
        "semantic_metadata": {"direct_v2_modifier": _metadata_safe_value(modifier)},
    }
    if primitive_type == "trim_band":
        kwargs.update(
            {
                "length": length,
                "width": width,
                "thickness": thickness,
                "length_axis": length_axis,
                "width_axis": width_axis,
            }
        )
    else:
        kwargs.update(
            {
                "width": length,
                "height": width,
                "thickness": thickness,
                "width_axis": length_axis,
                "height_axis": width_axis,
            }
        )
    try:
        attachment = _primitive_mesh(ShapePrimitive(**kwargs))
    except (TypeError, ValueError, RuntimeError, AttributeError, OSError, ContractViolation) as exc:
        return mesh, {
            "operation": operation,
            "geometry_application": "direct_attachment_concatenation_failed",
            "failure_reason": f"{type(exc).__name__}: {exc}",
        }
    details = {
        "operation": operation,
        "geometry_application": "direct_attachment_concatenated_mesh",
        "geometry_applied": True,
        "component": component,
        "normal_axis": normal_axis,
        "normal_sign": normal_sign,
        "length_axis": length_axis,
        "width_axis": width_axis,
        "length_cm": length,
        "width_cm": width,
        "thickness_cm": thickness,
        "direct_modifier": _metadata_safe_value(modifier),
        "source_face_count": int(len(mesh.faces)),
        "source_vertex_count": int(len(mesh.vertices)),
        "attachment_face_count": int(len(attachment.faces)),
        "attachment_vertex_count": int(len(attachment.vertices)),
    }
    return _direct_attachment_concat_mesh(mesh, attachment, name=name, details=details), details


