def _direct_modifier_source_param_is_lowerable(value: Any) -> bool:
    if isinstance(value, dict):
        return "primitive_type" in value or "op" in value
    return bool(hasattr(value, "op") and hasattr(value, "parameters"))


def _remove_non_geometry_direct_param(
    parameters: dict[str, Any],
    key: str,
    *,
    authoring_key: str,
) -> None:
    if key not in parameters:
        return
    value = parameters.get(key)
    if _direct_modifier_source_param_is_lowerable(value):
        return
    if value not in (None, "", (), [], {}):
        parameters.setdefault(authoring_key, str(value))
    parameters.pop(key, None)


def _remove_non_geometry_direct_source(parameters: dict[str, Any]) -> None:
    _remove_non_geometry_direct_param(
        parameters,
        "source",
        authoring_key="source_authoring",
    )


def _copy_first_direct_parameter_alias(
    parameters: dict[str, Any],
    canonical_key: str,
    aliases: tuple[str, ...],
) -> None:
    if canonical_key in parameters:
        return
    for alias in aliases:
        if alias in parameters:
            parameters[canonical_key] = parameters[alias]
            return


def _copy_first_direct_geometry_alias(
    parameters: dict[str, Any],
    canonical_key: str,
    aliases: tuple[str, ...],
) -> None:
    if canonical_key in parameters and _direct_modifier_source_param_is_lowerable(parameters[canonical_key]):
        return
    _remove_non_geometry_direct_param(
        parameters,
        canonical_key,
        authoring_key=f"{canonical_key}_authoring",
    )
    for alias in aliases:
        if alias not in parameters:
            continue
        value = parameters[alias]
        if _direct_modifier_source_param_is_lowerable(value):
            parameters[canonical_key] = value
            parameters.setdefault(f"{canonical_key}_alias", alias)
            return


