def _normalise_direct_construction_parameters(name: str, parameters: dict[str, Any]) -> None:
    for canonical_key, aliases in _DIRECT_CONSTRUCTION_PARAMETER_ALIASES.items():
        _copy_first_direct_parameter_alias(parameters, canonical_key, aliases)
    if "axis" not in parameters and "normal_axis" in parameters:
        parameters["axis"] = parameters["normal_axis"]
    if name == "v2_flange_modifier":
        _copy_first_direct_parameter_alias(
            parameters,
            "bore_radius_cm",
            ("bore_radius", "inner_radius_cm", "inner_radius"),
        )
    if name == "v2_corner_guard_set_modifier":
        if "size_cm" not in parameters and "guard_size_cm" in parameters:
            parameters["size_cm"] = parameters["guard_size_cm"]
        if "axes" not in parameters and "guard_axes" in parameters:
            parameters["axes"] = parameters["guard_axes"]
    if name == "v2_weld_seam_modifier" and "width_cm" not in parameters and "radius_cm" in parameters:
        try:
            parameters["width_cm"] = max(float(parameters["radius_cm"]) * 2.0, NUMERIC_EPSILON)
        except (TypeError, ValueError):
            pass
    if name == "v2_trim_band_modifier":
        _copy_first_direct_parameter_alias(parameters, "width_cm", ("band_width_cm", "width"))
        _copy_first_direct_parameter_alias(parameters, "frame_height_cm", ("height_cm", "height"))
    if name == "v2_panel_frame_modifier":
        _copy_first_direct_parameter_alias(parameters, "width_cm", ("length_cm", "length", "width"))
        _copy_first_direct_parameter_alias(parameters, "height_cm", ("frame_height_cm", "height"))
        _copy_first_direct_parameter_alias(parameters, "border_width_cm", ("border_width", "band_width_cm"))
        if "normal_axis" not in parameters and "axis" in parameters:
            parameters["normal_axis"] = parameters["axis"]
    if name == "v2_panel_modifier":
        _copy_first_direct_parameter_alias(parameters, "width_cm", ("length_cm", "length", "width"))
        _copy_first_direct_parameter_alias(parameters, "height_cm", ("panel_height_cm", "height"))
        _copy_first_direct_parameter_alias(parameters, "thickness_cm", ("thickness",))
        if "axis" not in parameters and "normal_axis" in parameters:
            parameters["axis"] = parameters["normal_axis"]
    if name == "v2_countersunk_hole_set_modifier":
        _copy_first_direct_parameter_alias(parameters, "radius_cm", ("radius",))
        _copy_first_direct_parameter_alias(parameters, "depth_cm", ("depth",))
        _copy_first_direct_parameter_alias(parameters, "rows", ("hole_rows",))
        _copy_first_direct_parameter_alias(parameters, "columns", ("hole_columns",))
        if "axis" not in parameters and "normal_axis" in parameters:
            parameters["axis"] = parameters["normal_axis"]
    if name == "v2_ribbed_panel_modifier":
        _copy_first_direct_parameter_alias(parameters, "width_cm", ("width",))
        _copy_first_direct_parameter_alias(parameters, "height_cm", ("height",))
        _copy_first_direct_parameter_alias(parameters, "thickness_cm", ("thickness",))
        _copy_first_direct_parameter_alias(parameters, "rib_count", ("count",))
        if "axis" not in parameters and "normal_axis" in parameters:
            parameters["axis"] = parameters["normal_axis"]
    if name == "v2_louver_panel_modifier":
        _copy_first_direct_parameter_alias(parameters, "width_cm", ("width",))
        _copy_first_direct_parameter_alias(parameters, "height_cm", ("height",))
        _copy_first_direct_parameter_alias(parameters, "thickness_cm", ("thickness",))
        _copy_first_direct_parameter_alias(parameters, "slat_count", ("count",))
        _copy_first_direct_parameter_alias(parameters, "slat_spacing_cm", ("slat_spacing", "spacing_cm"))
        if "axis" not in parameters and "normal_axis" in parameters:
            parameters["axis"] = parameters["normal_axis"]
    if name == "v2_perforated_panel_modifier":
        _copy_first_direct_parameter_alias(parameters, "width_cm", ("width",))
        _copy_first_direct_parameter_alias(parameters, "height_cm", ("height",))
        _copy_first_direct_parameter_alias(parameters, "thickness_cm", ("thickness",))
        _copy_first_direct_parameter_alias(parameters, "hole_radius_cm", ("hole_radius", "radius_cm", "radius"))
        _copy_first_direct_parameter_alias(parameters, "rows", ("hole_rows",))
        _copy_first_direct_parameter_alias(parameters, "columns", ("hole_columns",))
        _copy_first_direct_parameter_alias(parameters, "row_span_cm", ("row_span",))
        _copy_first_direct_parameter_alias(parameters, "column_span_cm", ("column_span",))
        _copy_first_direct_parameter_alias(parameters, "edge_margin_cm", ("edge_margin",))
        _copy_first_direct_parameter_alias(parameters, "slot_length_cm", ("slot_length",))
        if "axis" not in parameters and "normal_axis" in parameters:
            parameters["axis"] = parameters["normal_axis"]
    if name == "v2_socket_modifier":
        _copy_first_direct_parameter_alias(parameters, "clearance_cm", ("clearance",))
        _copy_first_direct_parameter_alias(parameters, "width_cm", ("width",))
        _copy_first_direct_parameter_alias(parameters, "height_cm", ("height",))
        _copy_first_direct_parameter_alias(parameters, "depth_cm", ("depth",))
        _copy_first_direct_parameter_alias(parameters, "rim_bevel_cm", ("bevel_width_cm",))
        if "axis" not in parameters and "normal_axis" in parameters:
            parameters["axis"] = parameters["normal_axis"]
        if "socket_shape" not in parameters and "style" in parameters:
            parameters["socket_shape"] = parameters["style"]
        if "clearance_cm" not in parameters and "width_cm" in parameters and "height_cm" in parameters:
            with suppress(TypeError, ValueError):
                parameters["clearance_cm"] = max(
                    min(float(parameters["width_cm"]), float(parameters["height_cm"])) * 0.5,
                    NUMERIC_EPSILON,
                )
    if name == "v2_cut_panel_line_modifier":
        _copy_first_direct_parameter_alias(parameters, "width_cm", ("opening_width_cm", "panel_width_cm", "width"))
        _copy_first_direct_parameter_alias(parameters, "length_cm", ("opening_length_cm", "length"))
        _copy_first_direct_parameter_alias(parameters, "depth_cm", ("depth",))
        _copy_first_direct_parameter_alias(parameters, "bevel_width_cm", ("rim_bevel_cm",))
        if "normal_axis" not in parameters and "axis" in parameters:
            parameters["normal_axis"] = parameters["axis"]
    if name == "v2_inset_modifier":
        _copy_first_direct_parameter_alias(parameters, "depth_cm", ("depth",))
        _copy_first_direct_parameter_alias(parameters, "margin_cm", ("edge_margin_cm", "margin"))
        _copy_first_direct_parameter_alias(parameters, "bevel_width_cm", ("rim_bevel_cm",))
        if "normal_axis" not in parameters and "axis" in parameters:
            parameters["normal_axis"] = parameters["axis"]
    if name == "v2_shell_modifier":
        _copy_first_direct_parameter_alias(parameters, "thickness_cm", ("thickness",))
        _copy_first_direct_parameter_alias(parameters, "rim_bevel_cm", ("bevel_width_cm",))
        if "open_axis" not in parameters and "axis" in parameters:
            parameters["open_axis"] = parameters["axis"]


def _direct_construction_lowering_records(
    name: str,
    modifier: dict[str, Any],
    primitive: ShapePrimitive,
    *,
    source_mesh: trimesh.Trimesh | None = None,
    geometry_kernel: Any | None = None,
) -> list[dict[str, Any]]:
    op_name = _DIRECT_CONSTRUCTION_LOWERER_OPS.get(name)
    if not op_name:
        raise ValueError(f"{name} has no direct construction lowerer")
    from .asset_quality.shape_ir_v2 import _V1_LOWERERS

    lowerer = _V1_LOWERERS.get(op_name)
    if lowerer is None:
        raise ValueError(f"{name} has no ShapeIR v2 lowerer for {op_name}")
    parameters = dict(modifier)
    _remove_non_geometry_direct_source(parameters)
    _normalise_direct_construction_parameters(name, parameters)
    source_backed = name in _DIRECT_CONSTRUCTION_SOURCE_BACKED_LOWERERS
    if source_backed and "source" not in parameters:
        source = (
            _direct_modifier_source_mesh_record(primitive, source_mesh)
            if source_mesh is not None
            else None
        )
        if source is None:
            source = _direct_modifier_source_box_record(primitive)
        if source is not None:
            parameters["source"] = source
    if not (source_backed and "source" in parameters):
        parameters.setdefault("center", tuple(float(value) for value in primitive.center))
    lowered = lowerer(
        _normalized_direct_shape_op(
            op_name=op_name,
            target=primitive.part or str(parameters.get("target") or "construction"),
            parameters=parameters,
            purpose=str(parameters.get("purpose") or "direct_exact_solids_modifier"),
        ),
        geometry_kernel=geometry_kernel,
    )
    if isinstance(lowered, dict):
        return [dict(lowered)]
    if isinstance(lowered, (list, tuple)):
        records = [dict(record) for record in lowered if isinstance(record, dict)]
        if records:
            return records
    raise ValueError(f"{name} lowerer did not produce any primitive records")


def _mesh_from_lowered_records(
    records: list[dict[str, Any]],
) -> tuple[trimesh.Trimesh, list[ShapePrimitive], list[str], dict[str, Any]]:
    child_primitives = [
        child
        for child in (_shape_primitive_from_metadata_record(record) for record in records)
        if child is not None
    ]
    if len(child_primitives) != len(records):
        raise ValueError("lowered records could not all be imported as ShapePrimitive values")
    blend_modes = [str(record.get("blend_mode") or "union").strip().lower() for record in records]
    meshes = [_primitive_mesh(child) for child in child_primitives]
    if not meshes or any(len(item.vertices) == 0 or len(item.faces) == 0 for item in meshes):
        raise ValueError("lowered records produced an empty mesh")
    if all(mode == "union" for mode in blend_modes):
        result = trimesh.util.concatenate(meshes) if len(meshes) > 1 else meshes[0].copy()
        result.remove_unreferenced_vertices()
        result.merge_vertices()
        result.fix_normals()
        return result, child_primitives, blend_modes, {
            "combine_mode": "union_concatenation",
            "combine_succeeded": True,
            "fallback_reason": "",
        }
    result, mode, succeeded, fallback_reason, seam_groups, polybevel_stats, boolean_details = _combine_explicit_meshes(
        meshes,
        blend_modes,
        child_primitives,
        combine_mode="kernel_program",
    )
    return result, child_primitives, blend_modes, {
        "combine_mode": mode,
        "combine_succeeded": bool(succeeded),
        "fallback_reason": fallback_reason or "",
        "post_boolean_seam_group_count": len(seam_groups),
        "post_boolean_polybevel": _metadata_safe_value(polybevel_stats),
        "boolean_details": _metadata_safe_value(boolean_details),
    }


def _lowered_record_kernel_source_modifier(record: dict[str, Any], modifier_name: str) -> dict[str, Any]:
    modifier = record.get(modifier_name)
    if isinstance(modifier, dict):
        return modifier
    semantic_metadata = record.get("semantic_metadata")
    if isinstance(semantic_metadata, dict):
        nested_v2 = semantic_metadata.get("shape_ir_v2")
        if isinstance(nested_v2, dict):
            modifier = nested_v2.get(modifier_name)
            if isinstance(modifier, dict):
                return modifier
    return {}


def _lowered_record_is_kernel_source_result(record: dict[str, Any], modifier_name: str) -> bool:
    modifier = _lowered_record_kernel_source_modifier(record, modifier_name)
    if not isinstance(modifier, dict) or not isinstance(modifier.get("kernel_program"), dict):
        return False
    if not record.get("mesh_vertices") or not record.get("mesh_faces"):
        return False
    return any(
        key in modifier
        for key in (
            "source_record_count",
            "source_primitive_type",
            "kernel_boolean_method",
            "source_part",
        )
    )


def _direct_v2_construction_lowerer_modifier_mesh(
    primitive: ShapePrimitive,
    mesh: trimesh.Trimesh,
    *,
    name: str,
    modifier: dict[str, Any],
    has_prior_applications: bool = False,
) -> tuple[trimesh.Trimesh, dict[str, Any]]:
    operation = str(_DIRECT_CONSTRUCTION_LOWERER_OPS.get(name) or "construction")
    if name == "v2_prism_modifier" and has_prior_applications:
        return mesh, {
            "operation": operation,
            "geometry_application": "direct_source_replacement_blocked_after_prior_modifier",
            "failure_reason": "direct v2_prism_modifier would replace prior modifier geometry; apply it before attachments or bake a construction_feature_mesh source",
        }
    kernel_program_failure = ""
    kernel_program_failure_fields: dict[str, Any] = {}
    geometry_application = "direct_shape_ir_v2_construction_lowering"
    try:
        from .geometry import resolve_geometry_kernel

        geometry_kernel = resolve_geometry_kernel(None)
        records = _direct_construction_lowering_records(
            name,
            modifier,
            primitive,
            source_mesh=mesh,
            geometry_kernel=geometry_kernel,
        )
        geometry_application = "kernel_program_construction_lowering"
        feature_mesh, child_primitives, blend_modes, combine_details = _mesh_from_lowered_records(records)
    except (TypeError, ValueError, RuntimeError, AttributeError, ImportError, KeyError, OSError, ContractViolation) as exc:
        kernel_program_failure = _exception_summary(exc)
        kernel_program_failure_fields = _exception_failure_fields(
            exc,
            prefix="kernel_program_construction_lowering_",
        )
        try:
            records = _direct_construction_lowering_records(
                name,
                modifier,
                primitive,
                source_mesh=mesh,
            )
            feature_mesh, child_primitives, blend_modes, combine_details = _mesh_from_lowered_records(records)
        except (TypeError, ValueError, RuntimeError, AttributeError, ImportError, KeyError, OSError, ContractViolation) as fallback_exc:
            return mesh, {
                "operation": operation,
                "geometry_application": "direct_construction_lowering_failed",
                "kernel_program_construction_lowering_failed": kernel_program_failure,
                **kernel_program_failure_fields,
                **_exception_failure_fields(fallback_exc),
            }
    details = {
        "operation": operation,
        "geometry_application": geometry_application,
        "geometry_applied": True,
        "kernel_program_construction_lowering_attempted": True,
        "kernel_program_construction_lowering_failed": kernel_program_failure,
        **kernel_program_failure_fields,
        "lowered_record_count": len(records),
        "lowered_primitive_types": [child.primitive_type for child in child_primitives],
        "lowered_blend_modes": blend_modes,
        "direct_modifier": _metadata_safe_value(modifier),
        "source_face_count": int(len(mesh.faces)),
        "source_vertex_count": int(len(mesh.vertices)),
        "feature_face_count": int(len(feature_mesh.faces)),
        "feature_vertex_count": int(len(feature_mesh.vertices)),
        **combine_details,
    }
    if (
        geometry_application == "kernel_program_construction_lowering"
        and name in _DIRECT_CONSTRUCTION_SOURCE_BACKED_LOWERERS
        and len(records) == 1
        and _lowered_record_is_kernel_source_result(records[0], name)
    ):
        result = feature_mesh
        details.update(
            {
                "geometry_application": "kernel_program_source_construction_lowering",
                "kernel_program_source_result_reused": True,
                "result_face_count": int(len(result.faces)),
                "result_vertex_count": int(len(result.vertices)),
                "result_watertight": bool(result.is_watertight),
                "result_body_count": _mesh_body_count(result),
            }
        )
        return _merge_direct_modifier_mesh_metadata(mesh, result, name=name, details=details), details
    if name != "v2_prism_modifier":
        if all(mode == "union" for mode in blend_modes):
            result = _direct_attachment_concat_mesh(mesh, feature_mesh, name=name, details=details)
            details.update(
                {
                    "result_face_count": int(len(result.faces)),
                    "result_vertex_count": int(len(result.vertices)),
                    "result_watertight": bool(result.is_watertight),
                    "result_body_count": _mesh_body_count(result),
                }
            )
            result.metadata[_v2_direct_modifier_metadata_key(name)] = dict(details)
            return result, details
        source_record = _direct_modifier_source_mesh_record(primitive, mesh)
        source_primitive = _shape_primitive_from_metadata_record(source_record) if source_record is not None else None
        if source_primitive is None:
            return mesh, {
                "operation": operation,
                "geometry_application": "direct_construction_boolean_source_failed",
                "failure_reason": f"could not wrap current mesh as source for non-union {name} construction",
            }
        try:
            result, mode, succeeded, fallback_reason, seam_groups, polybevel_stats, boolean_details = _combine_explicit_meshes(
                [mesh.copy(), feature_mesh],
                ["union", str(blend_modes[0] if blend_modes else "union")],
                [source_primitive, dataclass_replace(child_primitives[0], blend_mode=str(blend_modes[0] if blend_modes else "union"))],
                combine_mode="kernel_program",
            )
        except (TypeError, ValueError, RuntimeError, AttributeError, OSError, ContractViolation) as exc:
            return mesh, {
                "operation": operation,
                "geometry_application": "direct_construction_boolean_failed",
                "failure_reason": f"{type(exc).__name__}: {exc}",
            }
        details.update(
            {
                "geometry_application": "direct_shape_ir_v2_construction_boolean_mesh",
                "boolean_mode": mode,
                "boolean_succeeded": bool(succeeded),
                "fallback_reason": fallback_reason or "",
                "post_boolean_seam_group_count": len(seam_groups),
                "post_boolean_polybevel": _metadata_safe_value(polybevel_stats),
                "boolean_details": _metadata_safe_value(boolean_details),
                "result_face_count": int(len(result.faces)),
                "result_vertex_count": int(len(result.vertices)),
                "result_watertight": bool(result.is_watertight),
                "result_body_count": _mesh_body_count(result),
            }
        )
        return _merge_direct_modifier_mesh_metadata(mesh, result, name=name, details=details), details
    details.update(
        {
            "result_face_count": int(len(feature_mesh.faces)),
            "result_vertex_count": int(len(feature_mesh.vertices)),
            "result_watertight": bool(feature_mesh.is_watertight),
            "result_body_count": _mesh_body_count(feature_mesh),
        }
    )
    return _merge_direct_modifier_mesh_metadata(mesh, feature_mesh, name=name, details=details), details


