def _modifier_operation_default(modifier_name: str) -> str:
    token = str(modifier_name or "").strip()
    if token.startswith("v2_"):
        token = token[3:]
    if token.endswith("_modifier"):
        token = token[:-9]
    return _MODIFIER_OPERATION_DEFAULTS.get(token, f"modifier.{token or 'unknown'}")


def _primitive_operation_id(primitive: ShapePrimitive, index: int) -> str:
    metadata = _dict_metadata(primitive.semantic_metadata)
    v2_metadata = _dict_metadata(metadata.get("shape_ir_v2"))
    repair_metadata = _dict_metadata(metadata.get("semantic_repair"))
    modifier_operation_id = None
    for _modifier_name, modifier_metadata in _compound_modifier_payloads(primitive):
        if modifier_metadata.get("operation_id"):
            modifier_operation_id = modifier_metadata["operation_id"]
            break
    operation = (
        v2_metadata.get("v2_op")
        or repair_metadata.get("lowered_operation")
        or metadata.get("operation")
        or primitive.component
        or primitive.primitive_type
    )
    if "feature" in [str(tag) for tag in primitive.tags] and not any(
        (
            v2_metadata.get("operation_id"),
            repair_metadata.get("operation_id"),
            metadata.get("operation_id"),
        )
    ):
        return f"feature.{_operation_id_fragment(str(primitive.component or primitive.primitive_type or 'feature'))}"
    return str(
        v2_metadata.get("operation_id")
        or repair_metadata.get("operation_id")
        or metadata.get("operation_id")
        or modifier_operation_id
        or f"primitive:{index:04d}:{_operation_id_fragment(str(operation))}"
    )


_COMPOUND_MODIFIER_COUNT_KEYS = (
    "hole_count",
    "fastener_count",
    "slat_count",
    "rib_count",
    "cross_rib_count",
    "branch_count",
    "root_count",
    "blob_count",
    "placement_count",
    "module_record_count",
    "window_cell_count",
    "source_record_count",
    "source_record_expansion_count",
    "instance_transform_count",
    "result_face_count",
    "result_vertex_count",
    "count",
    "final_count",
    "instance_count",
)


def _compound_modifier_containers(primitive: ShapePrimitive) -> list[dict[str, Any]]:
    metadata = _dict_metadata(getattr(primitive, "semantic_metadata", None))
    containers = [metadata]
    baked_source_modifiers = _dict_metadata(metadata.get("shape_ir_v2_baked_source_modifiers"))
    if baked_source_modifiers:
        containers.append(baked_source_modifiers)
    nested_values = [
        metadata.get("shape_ir_v2"),
        metadata.get("source_shape_primitive"),
        *[
            item
            for item in metadata.get("source_shape_primitives", [])
            if isinstance(item, dict)
        ],
    ]
    for value in nested_values:
        nested = _dict_metadata(value)
        if nested:
            containers.append(nested)
            nested_baked = _dict_metadata(nested.get("shape_ir_v2_baked_source_modifiers"))
            if nested_baked:
                containers.append(nested_baked)
            nested_semantic = _dict_metadata(nested.get("semantic_metadata"))
            if nested_semantic:
                containers.append(nested_semantic)
                semantic_baked = _dict_metadata(
                    nested_semantic.get("shape_ir_v2_baked_source_modifiers")
                )
                if semantic_baked:
                    containers.append(semantic_baked)
                nested_v2 = _dict_metadata(nested_semantic.get("shape_ir_v2"))
                if nested_v2:
                    containers.append(nested_v2)
    return containers


def _compound_modifier_payloads(primitive: ShapePrimitive) -> list[tuple[str, dict[str, Any]]]:
    payloads: list[tuple[str, dict[str, Any]]] = []
    seen: set[tuple[str, str, str]] = set()

    def add_payload(name: Any, value: Any) -> None:
        if not (
            isinstance(name, str)
            and name.startswith("v2_")
            and name.endswith("_modifier")
            and isinstance(value, dict)
        ):
            return
        payload = dict(value)
        key = (
            name,
            str(payload.get("method") or ""),
            str(payload.get("operation_id") or payload.get("target") or ""),
        )
        if key in seen:
            return
        seen.add(key)
        payloads.append((name, payload))

    for container in _compound_modifier_containers(primitive):
        for name, value in container.items():
            add_payload(name, value)
    for name, value in vars(primitive).items():
        add_payload(name, value)
    return payloads


def _metadata_safe_value(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(key): _metadata_safe_value(item) for key, item in value.items()}
    if isinstance(value, tuple):
        return [_metadata_safe_value(item) for item in value]
    if isinstance(value, list):
        return [_metadata_safe_value(item) for item in value]
    if isinstance(value, np.ndarray):
        return _metadata_safe_value(value.tolist())
    if isinstance(value, np.generic):
        return value.item()
    return value


def _attach_v2_modifier_metadata(
    primitive: ShapePrimitive,
    mesh: trimesh.Trimesh,
) -> trimesh.Trimesh:
    payloads = _compound_modifier_payloads(primitive)
    if not payloads:
        return mesh

    records = [
        {"name": name, "payload": _metadata_safe_value(payload)}
        for name, payload in payloads
    ]
    grouped: dict[str, list[dict[str, Any]]] = {}
    for record in records:
        grouped.setdefault(str(record["name"]), []).append(record["payload"])

    modifier_names = sorted(grouped)
    v2_metadata = _v2_semantic_metadata(primitive)
    existing = mesh.metadata.get("lathe_shape_ir_v2_modifiers")
    existing = existing if isinstance(existing, dict) else {}
    existing_records = existing.get("modifier_records")
    existing_records = existing_records if isinstance(existing_records, list) else []
    existing_grouped = existing.get("modifiers_by_name")
    existing_grouped = existing_grouped if isinstance(existing_grouped, dict) else {}
    merged_grouped: dict[str, list[dict[str, Any]]] = {
        str(name): [dict(item) for item in values if isinstance(item, dict)]
        for name, values in existing_grouped.items()
        if isinstance(values, list)
    }
    for name, values in grouped.items():
        merged_grouped[name] = [dict(item) for item in values]

    merged_names = sorted(merged_grouped)
    mesh.metadata["lathe_shape_ir_v2_modifiers"] = {
        **existing,
        "schema": "lathe.exact_solids.shape_ir_v2_modifiers.v1",
        "method": "source_modifier_metadata_preservation_v1",
        "source_primitive_type": primitive.primitive_type,
        "part": primitive.part,
        "operation": str(v2_metadata.get("v2_op") or existing.get("operation") or ""),
        "semantic_state": "metadata_preserved",
        "geometry_application": "modifier_specific_metadata_or_downstream_stage",
        "modifier_count": len(merged_names),
        "modifier_names": merged_names,
        "generic_modifier_names": [
            name for name in merged_names if name in _GENERIC_V2_MODIFIER_KEYS
        ],
        "modifier_records": [
            *existing_records,
            *records,
        ],
        "modifiers_by_name": merged_grouped,
    }
    return mesh


def _primitive_v2_modifier_records(
    primitives: list[ShapePrimitive],
    blend_modes: list[str],
) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for index, primitive in enumerate(primitives):
        v2_metadata = _v2_semantic_metadata(primitive)
        for name, payload in _compound_modifier_payloads(primitive):
            geometry_application = (
                _v2_transform_geometry_application(primitive, payload)
                if name == "v2_transform_modifier"
                else _instance_modifier_geometry_application(name, payload)
            )
            modifier_operation = _modifier_operation_default(name)
            records.append(
                {
                    "name": name,
                    "primitive_index": index,
                    "primitive_type": primitive.primitive_type,
                    "part": primitive.part,
                    "blend_mode": blend_modes[index] if index < len(blend_modes) else "",
                    "operation": str(
                        payload.get("v2_op")
                        or payload.get("operation")
                        or v2_metadata.get("v2_op")
                        or modifier_operation
                    ),
                    "semantic_state": "metadata_preserved",
                    "geometry_application": geometry_application,
                    "geometry_applied": geometry_application
                    in {
                        "exact_solids_transform_matrix",
                        "modifier_already_marked_applied",
                        "source_record_baked_transform",
                        "kernel_program_baked_mesh",
                        "mesh_backed_result_already_transformed",
                        "exact_solids_instance_transform",
                        "source_record_or_kernel_transform",
                    },
                    "generic": name in _GENERIC_V2_MODIFIER_KEYS,
                    "payload": _metadata_safe_value(payload),
                }
            )
    return records


def _source_mesh_metadata_records(
    meshes: list[trimesh.Trimesh],
    metadata_key: str,
) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for mesh in meshes:
        metadata = getattr(mesh, "metadata", None)
        if not isinstance(metadata, dict):
            continue
        value = metadata.get(metadata_key)
        if isinstance(value, dict):
            records.append(dict(value))
        elif isinstance(value, list):
            records.extend(dict(item) for item in value if isinstance(item, dict))
    return records


def _material_hint_from_containers(containers: list[dict[str, Any]]) -> str:
    for container in containers:
        for key in ("material_hint", "material_zone", "material", "zone"):
            value = container.get(key)
            if value in (None, "", (), [], {}):
                continue
            if isinstance(value, dict):
                for nested_key in ("material_hint", "material", "name", "zone"):
                    nested = value.get(nested_key)
                    if nested not in (None, "", (), [], {}):
                        return str(nested)
                continue
            return str(value)
    return ""


def _primitive_material_zone_candidates(
    primitives: list[ShapePrimitive],
    blend_modes: list[str],
) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    for index, primitive in enumerate(primitives):
        blend_mode = blend_modes[index] if index < len(blend_modes) else _blend_mode(primitive)
        if blend_mode == "subtract":
            continue
        tags = [str(tag) for tag in primitive.tags if str(tag)]
        material_hint = _material_hint_from_containers(
            _compound_modifier_containers(primitive)
        ) or str(primitive.component or "")
        if not ("material_zone" in tags or "wear_zone" in tags or material_hint):
            continue
        part = str(primitive.part or "mesh")
        candidates.append(
            {
                "name": f"exact_material_{len(candidates):03d}_{_operation_id_fragment(part)}",
                "part": primitive.part,
                "component": primitive.component or "",
                "region": primitive.region or "",
                "primitive_type": primitive.primitive_type,
                "material_hint": str(material_hint or primitive.primitive_type or "material"),
                "source": "shape_ir.primitive.semantic_handoff",
                "primitive_index": index,
                "blend_mode": blend_mode,
                "tags": tags,
            }
        )
    return candidates


def _positive_int_metadata(value: Any) -> int | None:
    if isinstance(value, bool):
        return None
    try:
        count = int(value)
    except (TypeError, ValueError):
        return None
    return count if count > 0 else None


def _compound_visible_counts(payload: dict[str, Any]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for key in _COMPOUND_MODIFIER_COUNT_KEYS:
        count = _positive_int_metadata(payload.get(key))
        if count is not None:
            counts[key] = count
    rows = _positive_int_metadata(payload.get("rows"))
    columns = _positive_int_metadata(payload.get("columns"))
    if rows is not None and columns is not None and "grid_cell_count" not in counts:
        counts["grid_cell_count"] = rows * columns
    floors = _positive_int_metadata(payload.get("floors"))
    bays = _positive_int_metadata(payload.get("bays"))
    if floors is not None and bays is not None and "floor_bay_cell_count" not in counts:
        counts["floor_bay_cell_count"] = floors * bays
    grid_shape = payload.get("grid_shape")
    if isinstance(grid_shape, (list, tuple)) and len(grid_shape) >= 2:
        grid_count = 1
        for value in grid_shape:
            dimension = _positive_int_metadata(value)
            if dimension is None:
                grid_count = 0
                break
            grid_count *= dimension
        if grid_count > 0 and "grid_shape_cell_count" not in counts:
            counts["grid_shape_cell_count"] = grid_count
    return counts


def _compound_operation_reports(primitives: list[ShapePrimitive]) -> list[dict[str, Any]]:
    reports: list[dict[str, Any]] = []
    for index, primitive in enumerate(primitives):
        metadata = _dict_metadata(getattr(primitive, "semantic_metadata", None))
        v2_metadata = _dict_metadata(metadata.get("shape_ir_v2"))
        source_metadata = _dict_metadata(metadata.get("source_shape_primitive"))
        operation = str(
            v2_metadata.get("v2_op")
            or source_metadata.get("v2_op")
            or primitive.component
            or primitive.primitive_type
        )
        operation_id = _primitive_operation_id(primitive, index)
        for modifier_name, payload in _compound_modifier_payloads(primitive):
            visible_counts = _compound_visible_counts(payload)
            kernel_program = _dict_metadata(payload.get("kernel_program"))
            exact_cut_count = _positive_int_metadata(
                kernel_program.get("kernel_program_exact_profile_cut_final_cut_count")
            )
            exact_chamfer_count = _positive_int_metadata(
                kernel_program.get("kernel_program_exact_profile_cut_final_chamfer_face_count")
            )
            exact_bevel_count = _positive_int_metadata(
                kernel_program.get("kernel_program_exact_profile_cut_final_bevel_face_count")
            )
            exact_rim_count = _positive_int_metadata(
                kernel_program.get("kernel_program_exact_profile_cut_final_rim_face_count")
            )
            if exact_cut_count is not None:
                visible_counts["profile_cut_count"] = exact_cut_count
            if exact_chamfer_count is not None:
                visible_counts["profile_cut_chamfer_face_count"] = exact_chamfer_count
            if exact_bevel_count is not None:
                visible_counts["profile_cut_bevel_face_count"] = exact_bevel_count
            if exact_rim_count is not None:
                visible_counts["profile_cut_rim_face_count"] = exact_rim_count
            post_boolean_attempted_bevel_count = _positive_int_metadata(
                kernel_program.get("post_boolean_polybevel_attempted_bevel_face_count")
            )
            post_boolean_fallback_face_count = _positive_int_metadata(
                kernel_program.get("post_boolean_polybevel_fallback_face_count")
            )
            post_boolean_fallback_vertex_count = _positive_int_metadata(
                kernel_program.get("post_boolean_polybevel_fallback_vertex_count")
            )
            post_boolean_visible_seam_strip_face_count = _positive_int_metadata(
                kernel_program.get("post_boolean_polybevel_visible_seam_strip_face_count")
            )
            post_boolean_visible_seam_strip_body_delta = _positive_int_metadata(
                kernel_program.get("post_boolean_polybevel_visible_seam_strip_body_count_delta")
            )
            post_boolean_visible_seam_strip_skipped_edges = _positive_int_metadata(
                kernel_program.get("post_boolean_polybevel_visible_seam_strip_skipped_edge_count")
            )
            if post_boolean_attempted_bevel_count is not None:
                visible_counts["post_boolean_polybevel_attempted_bevel_face_count"] = (
                    post_boolean_attempted_bevel_count
                )
            if post_boolean_fallback_face_count is not None:
                visible_counts["post_boolean_polybevel_fallback_face_count"] = (
                    post_boolean_fallback_face_count
                )
            if post_boolean_fallback_vertex_count is not None:
                visible_counts["post_boolean_polybevel_fallback_vertex_count"] = (
                    post_boolean_fallback_vertex_count
                )
            if post_boolean_visible_seam_strip_face_count is not None:
                visible_counts["post_boolean_polybevel_visible_seam_strip_face_count"] = (
                    post_boolean_visible_seam_strip_face_count
                )
            if post_boolean_visible_seam_strip_body_delta is not None:
                visible_counts["post_boolean_polybevel_visible_seam_strip_body_count_delta"] = (
                    post_boolean_visible_seam_strip_body_delta
                )
            if post_boolean_visible_seam_strip_skipped_edges is not None:
                visible_counts["post_boolean_polybevel_visible_seam_strip_skipped_edge_count"] = (
                    post_boolean_visible_seam_strip_skipped_edges
                )
            if not visible_counts:
                continue
            report: dict[str, Any] = {
                "primitive_index": index,
                "operation_id": operation_id,
                "operation": operation,
                "modifier": modifier_name,
                "part": primitive.part,
                "primitive_type": primitive.primitive_type,
                "visible_counts": visible_counts,
            }
            for key in (
                "method",
                "kernel",
                "kernel_selection",
                "result_face_count",
                "result_watertight",
            ):
                value = payload.get(key)
                if value not in (None, "", (), [], {}):
                    report[key] = value
            for key in (
                "kernel_program_operation_count",
                "kernel_program_kernel_call_count",
                "kernel_program_operand_count",
                "kernel_program_body_count",
                "kernel_program_boolean_fallback_count",
                "instances_count",
                "instances_actual_assembly_method",
                "instances_result_body_count",
                "kernel_program_exact_profile_cut_operation_count",
                "kernel_program_exact_profile_cut_final_cut_count",
                "kernel_program_exact_profile_cut_final_chamfer_face_count",
                "kernel_program_exact_profile_cut_final_bevel_face_count",
                "kernel_program_exact_profile_cut_final_rim_face_count",
                "kernel_program_exact_profile_cut_final_bore_wall_face_count",
                "post_boolean_polybevel_attempted_bevel_face_count",
                "post_boolean_polybevel_fallback_face_count",
                "post_boolean_polybevel_fallback_vertex_count",
                "post_boolean_polybevel_visible_seam_strip_face_count",
                "post_boolean_polybevel_visible_seam_strip_body_count_delta",
                "post_boolean_polybevel_visible_seam_strip_limit",
                "post_boolean_polybevel_visible_seam_strip_skipped_edge_count",
            ):
                value = kernel_program.get(key)
                if value not in (None, "", (), [], {}):
                    report[key] = value
            for key in (
                "post_boolean_polybevel_actual_method",
                "post_boolean_polybevel_fallback_method",
                "post_boolean_polybevel_rejected_reason",
            ):
                value = kernel_program.get(key)
                if value not in (None, "", (), [], {}):
                    report[key] = value
            for key in (
                "post_boolean_polybevel_fallback_accepted",
                "post_boolean_polybevel_visible_fallback_applied",
                "post_boolean_polybevel_visible_seam_strip_truncated",
            ):
                if key in kernel_program:
                    report[key] = bool(kernel_program.get(key))
            reports.append(report)
    return reports


def _source_face_operation_ids(
    primitives: list[ShapePrimitive],
    source_meshes: list[trimesh.Trimesh],
) -> list[str]:
    face_operation_ids: list[str] = []
    for index, (primitive, mesh) in enumerate(zip(primitives, source_meshes, strict=False)):
        metadata = getattr(mesh, "metadata", None)
        existing = (
            metadata.get("face_operation_ids")
            if isinstance(metadata, dict)
            else None
        )
        if isinstance(existing, list) and len(existing) == len(mesh.faces):
            face_operation_ids.extend(str(operation_id) for operation_id in existing)
            continue
        face_operation_ids.extend([_primitive_operation_id(primitive, index)] * len(mesh.faces))
    return face_operation_ids


def _face_operation_ids_from_primitive_indices(
    primitives: list[ShapePrimitive],
    primitive_indices: list[int],
) -> list[str]:
    operation_ids = [
        _primitive_operation_id(primitive, index)
        for index, primitive in enumerate(primitives)
    ]
    return [
        operation_ids[index] if 0 <= index < len(operation_ids) else "primitive:unknown"
        for index in primitive_indices
    ]


def _face_operation_summary(
    face_operation_ids: list[str],
    *,
    cut_operation_ids: list[str],
    source: str,
    compound_operations: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    operations = {
        operation_id: face_operation_ids.count(operation_id)
        for operation_id in sorted(set(face_operation_ids))
    }
    cut_operations = {
        operation_id: cut_operation_ids.count(operation_id)
        for operation_id in sorted(set(cut_operation_ids))
    }
    summary = {
        "schema": "lathe.mesh_ir.face_operation_summary.v1",
        "face_count": len(face_operation_ids),
        "operation_count": len(operations),
        "operations": operations,
        "cut_operations": cut_operations,
        "source": source,
    }
    if compound_operations:
        summary["compound_operations"] = compound_operations
        summary["compound_operation_count"] = len(compound_operations)
    return summary


def _primitive_operation_records(
    primitives: list[ShapePrimitive],
    blend_modes: list[str],
) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for index, primitive in enumerate(primitives):
        metadata = _dict_metadata(primitive.semantic_metadata)
        v2_metadata = _dict_metadata(metadata.get("shape_ir_v2"))
        repair_metadata = _dict_metadata(metadata.get("semantic_repair"))
        operation = (
            v2_metadata.get("v2_op")
            or repair_metadata.get("lowered_operation")
            or metadata.get("operation")
        )
        repair_action = repair_metadata.get("action") or v2_metadata.get("repair_action")
        operation_id = (
            v2_metadata.get("operation_id")
            or repair_metadata.get("operation_id")
            or metadata.get("operation_id")
        )
        surface_scatter = _dict_metadata(metadata.get("surface_scatter"))
        point_scatter = _dict_metadata(metadata.get("point_scatter"))
        sdf_extract_record = _sdf_extract_operation_record_metadata(metadata)
        if any((operation, repair_action, operation_id)):
            op_text = str(operation or repair_action or "primitive")
            record = {
                "operation_id": str(
                    operation_id
                    or f"primitive:{index:04d}:{_operation_id_fragment(op_text)}"
                ),
                "operation": str(operation or ""),
                "repair_action": str(repair_action or ""),
                "primitive_index": index,
                "part": primitive.part,
                "component": primitive.component or "",
                "region": primitive.region or "",
                "primitive_type": primitive.primitive_type,
                "blend_mode": blend_modes[index] if index < len(blend_modes) else _blend_mode(primitive),
                "source": "shape_ir.primitive.semantic_metadata",
            }
            if surface_scatter:
                record["surface_scatter"] = surface_scatter
            if point_scatter:
                record["point_scatter"] = point_scatter
            if sdf_extract_record:
                record["sdf_extract"] = sdf_extract_record
            records.append(record)
        elif "feature" in [str(tag) for tag in primitive.tags]:
            component = str(primitive.component or primitive.primitive_type or "feature")
            records.append(
                {
                    "operation_id": f"feature.{_operation_id_fragment(component)}",
                    "operation": f"feature.{component}",
                    "repair_action": "",
                    "primitive_index": index,
                    "part": primitive.part,
                    "component": primitive.component or "",
                    "region": primitive.region or "",
                    "primitive_type": primitive.primitive_type,
                    "blend_mode": blend_modes[index] if index < len(blend_modes) else _blend_mode(primitive),
                    "source": "shape_ir.primitive.feature_component",
                }
            )
        for modifier_name, modifier_metadata in _compound_modifier_payloads(primitive):
            modifier_operation = _modifier_operation_default(modifier_name)
            record = {
                "operation_id": str(
                    modifier_metadata.get("operation_id")
                    or f"primitive:{index:04d}:{_operation_id_fragment(modifier_operation)}"
                ),
                "operation": str(
                    modifier_metadata.get("v2_op")
                    or modifier_metadata.get("operation")
                    or modifier_operation
                ),
                "repair_action": str(repair_action or ""),
                "primitive_index": index,
                "part": primitive.part,
                "component": primitive.component or "",
                "region": primitive.region or "",
                "primitive_type": primitive.primitive_type,
                "blend_mode": blend_modes[index] if index < len(blend_modes) else _blend_mode(primitive),
                "source": modifier_name,
            }
            for key in (
                "method",
                "actual_method",
                "actual_backend",
                "actual_geometry_backend",
                "result_face_count",
                "result_vertex_count",
                "result_watertight",
                "source_face_count",
                "source_vertex_count",
            ):
                if key in modifier_metadata:
                    record[key] = _metadata_safe_value(modifier_metadata[key])
            records.append(record)
    deduped: list[dict[str, Any]] = []
    seen: set[tuple[str, str, int, str]] = set()
    for record in records:
        key = (
            str(record.get("operation_id") or ""),
            str(record.get("operation") or ""),
            int(record.get("primitive_index") or 0),
            str(record.get("source") or ""),
        )
        if key in seen:
            continue
        seen.add(key)
        deduped.append(record)
    return deduped


def _operation_counts(records: list[dict[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for record in records:
        operation = str(record.get("operation") or record.get("repair_action") or "")
        if not operation:
            continue
        counts[operation] = counts.get(operation, 0) + 1
    return dict(sorted(counts.items()))


def _topology_preserving_merge_vertices(mesh: trimesh.Trimesh) -> tuple[trimesh.Trimesh, dict[str, Any]]:
    before = _mesh_edge_topology_stats(mesh)
    candidate = mesh.copy()
    candidate.merge_vertices()
    after = _mesh_edge_topology_stats(candidate)
    accepted = True
    rejected_reason = ""
    if before["watertight"] and not after["watertight"]:
        accepted = False
        rejected_reason = "merge_vertices_broke_watertightness"
    elif after["boundary_edge_count"] > before["boundary_edge_count"]:
        accepted = False
        rejected_reason = "merge_vertices_added_boundary_edges"
    elif after["nonmanifold_edge_count"] > before["nonmanifold_edge_count"]:
        accepted = False
        rejected_reason = "merge_vertices_added_nonmanifold_edges"
    elif before["body_count"] and after["body_count"] > before["body_count"]:
        accepted = False
        rejected_reason = "merge_vertices_increased_body_count"
    stats = {
        "method": "topology_preserving_merge_vertices_v1",
        "accepted": bool(accepted),
        "source_vertex_count": int(before["vertex_count"]),
        "candidate_vertex_count": int(after["vertex_count"]),
        "source_face_count": int(before["face_count"]),
        "candidate_face_count": int(after["face_count"]),
        "source_boundary_edge_count": int(before["boundary_edge_count"]),
        "candidate_boundary_edge_count": int(after["boundary_edge_count"]),
        "source_nonmanifold_edge_count": int(before["nonmanifold_edge_count"]),
        "candidate_nonmanifold_edge_count": int(after["nonmanifold_edge_count"]),
        "source_body_count": int(before["body_count"]),
        "candidate_body_count": int(after["body_count"]),
        "source_watertight": bool(before["watertight"]),
        "candidate_watertight": bool(after["watertight"]),
    }
    if rejected_reason:
        stats["rejected_reason"] = rejected_reason
    return (candidate if accepted else mesh), stats


_SDF_EXTRACT_OPERATION_RECORD_KEYS = (
    "topology_method",
    "source_vertex_count",
    "source_face_count",
    "source_unique_edge_count",
    "source_boundary_edge_count",
    "source_nonmanifold_edge_count",
    "source_body_count",
    "source_watertight",
    "resolution",
    "requested_resolution",
    "resolution_source",
    "resolution_clamped",
    "bounds_source",
    "bounds_padding_cm",
)


def _sdf_extract_operation_record_metadata(metadata: dict[str, Any]) -> dict[str, Any]:
    sdf_extract = _dict_metadata(metadata.get("mesh_program_sdf_extract"))
    if not sdf_extract:
        return {}
    record: dict[str, Any] = {}
    for key in _SDF_EXTRACT_OPERATION_RECORD_KEYS:
        value = sdf_extract.get(key)
        if value not in (None, "", (), [], {}):
            record[key] = value
    backend = _dict_metadata(sdf_extract.get("extraction_backend"))
    if backend:
        record["extraction_backend"] = {
            key: value
            for key, value in backend.items()
            if value not in (None, "", (), [], {})
        }
    return record


def compile_explicit_surface_mesh(
    shape_ir: ShapeIR,
    fidelity: FidelityProfile,
    *,
    combine_mode: str = "explicit_mesh",
    geometry_kernel: Any | None = None,
) -> tuple[trimesh.Trimesh, list[str], dict[str, Any]]:
    """Compile ShapeIR primitives into an explicit trimesh surface mesh."""
    meshes: list[trimesh.Trimesh] = []
    blend_modes: list[str] = []
    face_parts: list[str] = []
    for primitive in shape_ir.primitives:
        mesh = _primitive_mesh(primitive)
        meshes.append(mesh)
        blend_modes.append(_blend_mode(primitive))
        face_parts.extend([primitive.part] * len(mesh.faces))

    if not meshes:
        return trimesh.Trimesh(), [], {"mode": "exact_explicit_assembly", "primitive_count": 0}

    (
        combined,
        mode,
        boolean_succeeded,
        boolean_fallback_reason,
        post_boolean_seam_groups,
        post_boolean_polybevel_stats,
        boolean_details,
    ) = _combine_explicit_meshes(
        meshes,
        blend_modes,
        list(shape_ir.primitives),
        combine_mode=combine_mode,
        geometry_kernel=geometry_kernel,
    )
    face_primitive_indices = (
        _assign_boolean_face_primitive_indices_from_bounds(
            combined,
            list(shape_ir.primitives),
            meshes,
            blend_modes,
        )
        if boolean_succeeded
        else []
    )
    face_parts_out = (
        [
            shape_ir.primitives[index].part
            if 0 <= index < len(shape_ir.primitives)
            else "mesh"
            for index in face_primitive_indices
        ]
        if boolean_succeeded
        else list(face_parts)
    )
    face_operation_ids = (
        _face_operation_ids_from_primitive_indices(
            list(shape_ir.primitives),
            face_primitive_indices,
        )
        if boolean_succeeded
        else _source_face_operation_ids(list(shape_ir.primitives), meshes)
    )
    cut_attributed_primitive_indices = [
        index
        for index in face_primitive_indices
        if 0 <= index < len(blend_modes) and blend_modes[index] in {"subtract", "intersect"}
    ]
    cut_attributed_operation_ids = [
        _primitive_operation_id(shape_ir.primitives[index], index)
        for index in cut_attributed_primitive_indices
        if 0 <= index < len(shape_ir.primitives)
    ]
    combined.remove_infinite_values()
    combined.remove_unreferenced_vertices()
    combined, merge_vertices_stats = _topology_preserving_merge_vertices(combined)
    combined.fix_normals()
    if len(face_operation_ids) != len(combined.faces):
        face_operation_ids = []
        cut_attributed_operation_ids = []
    face_operation_source = (
        "primitive_bounds_with_boolean_operands"
        if boolean_succeeded
        else "source_face_operations"
    )
    if fidelity.tier in {"hero", "cinematic"}:
        with suppress(ValueError, RuntimeError, AttributeError, IndexError):
            iterations = 2 if fidelity.tier == "cinematic" else 1
            trimesh.smoothing.filter_taubin(combined, lamb=0.18, nu=-0.19, iterations=iterations)
            combined.fix_normals()
    operation_records = _primitive_operation_records(list(shape_ir.primitives), blend_modes)
    material_zone_candidates = _primitive_material_zone_candidates(
        list(shape_ir.primitives),
        blend_modes,
    )
    shape_ir_v2_modifier_records = _primitive_v2_modifier_records(
        list(shape_ir.primitives),
        blend_modes,
    )
    shape_ir_v2_modifier_names = sorted(
        {
            str(record.get("name") or "")
            for record in shape_ir_v2_modifier_records
            if str(record.get("name") or "")
        }
    )
    context_aggregate_records = _source_mesh_metadata_records(
        meshes,
        "lathe_context_aggregate",
    )
    report = {
        "mode": mode,
        "primitive_count": len(shape_ir.primitives),
        "operation_record_count": len(operation_records),
        "operation_counts": _operation_counts(operation_records),
        "operation_records": operation_records,
        "material_zone_candidate_count": len(material_zone_candidates),
        "material_zone_candidate_part_count": len(
            {
                str(candidate.get("part") or "")
                for candidate in material_zone_candidates
            }
        ),
        "material_zone_candidate_material_count": len(
            {
                str(candidate.get("material_hint") or "")
                for candidate in material_zone_candidates
            }
        ),
        "material_zone_candidates": material_zone_candidates,
        "shape_ir_v2_modifier_record_count": len(shape_ir_v2_modifier_records),
        "shape_ir_v2_modifier_names": shape_ir_v2_modifier_names,
        "shape_ir_v2_generic_modifier_names": [
            name for name in shape_ir_v2_modifier_names if name in _GENERIC_V2_MODIFIER_KEYS
        ],
        "shape_ir_v2_modifier_summary": {
            "schema": "lathe.exact_solids.shape_ir_v2_modifier_summary.v1",
            "record_count": len(shape_ir_v2_modifier_records),
            "modifier_names": shape_ir_v2_modifier_names,
            "generic_modifier_names": [
                name for name in shape_ir_v2_modifier_names if name in _GENERIC_V2_MODIFIER_KEYS
            ],
            "semantic_state": "metadata_preserved",
            "geometry_application": "modifier_specific_metadata_or_downstream_stage",
        },
        "shape_ir_v2_modifier_records": shape_ir_v2_modifier_records,
        "context_aggregate_count": len(context_aggregate_records),
        "context_aggregate_child_count": sum(
            int(record.get("compiled_child_count") or 0)
            for record in context_aggregate_records
        ),
        "context_aggregates": context_aggregate_records,
        "merge_vertices": merge_vertices_stats,
        "boolean_operation_count": max(0, blend_modes.count("union") - 1)
        + blend_modes.count("subtract")
        + blend_modes.count("intersect"),
        "subtract_primitive_count": blend_modes.count("subtract"),
        "intersect_primitive_count": blend_modes.count("intersect"),
        "boolean_seam_group_count": sum(len(primitive.boolean_seam_groups) for primitive in shape_ir.primitives),
        "post_boolean_seam_group_count": len(post_boolean_seam_groups),
        "post_boolean_seam_loop_count": sum(
            int(group.get("loop_count", 0)) for group in post_boolean_seam_groups
        ),
        "post_boolean_seam_edge_count": sum(
            int(group.get("edge_count", 0)) for group in post_boolean_seam_groups
        ),
        "post_boolean_polybevel_group_count": int(
            post_boolean_polybevel_stats.get("group_count", 0)
        ),
        "post_boolean_polybevel_edge_count": int(
            post_boolean_polybevel_stats.get("edge_count", 0)
        ),
        "post_boolean_polybevel_face_count": int(
            post_boolean_polybevel_stats.get("face_count", 0)
        ),
        "post_boolean_polybevel_method": str(
            post_boolean_polybevel_stats.get("method", "")
        ),
        "post_boolean_polybevel_consumed_face_count": int(
            post_boolean_polybevel_stats.get("consumed_face_count", 0)
        ),
        "post_boolean_polybevel_strip_count": int(
            post_boolean_polybevel_stats.get("strip_count", 0)
        ),
        "post_boolean_polybevel_largest_strip_edge_count": int(
            post_boolean_polybevel_stats.get("largest_strip_edge_count", 0)
        ),
        "post_boolean_polybevel_reused_surface_face_count": int(
            post_boolean_polybevel_stats.get("reused_surface_face_count", 0)
        ),
        "post_boolean_polybevel_open_strip_count": int(
            post_boolean_polybevel_stats.get("open_strip_count", 0)
        ),
        "post_boolean_polybevel_closed_strip_count": int(
            post_boolean_polybevel_stats.get("closed_strip_count", 0)
        ),
        "post_boolean_polybevel_total_strip_uv_span_cm": float(
            post_boolean_polybevel_stats.get("total_strip_uv_span_cm", 0.0)
        ),
        "post_boolean_polybevel_largest_strip_uv_span_cm": float(
            post_boolean_polybevel_stats.get("largest_strip_uv_span_cm", 0.0)
        ),
        "post_boolean_polybevel_strip_uv_source": str(
            post_boolean_polybevel_stats.get("strip_uv_source", "")
        ),
        "post_boolean_polybevel_direct_uv_assignment": bool(
            post_boolean_polybevel_stats.get("direct_uv_assignment", False)
        ),
        "post_boolean_polybevel_generated_uv_vertex_count": int(
            post_boolean_polybevel_stats.get("generated_uv_vertex_count", 0)
        ),
        "post_boolean_polybevel_cutback_face_count": int(
            post_boolean_polybevel_stats.get("cutback_face_count", 0)
        ),
        "post_boolean_polybevel_bevel_face_count": int(
            post_boolean_polybevel_stats.get("bevel_face_count", 0)
        ),
        "post_boolean_polybevel_endpoint_cap_face_count": int(
            post_boolean_polybevel_stats.get("endpoint_cap_face_count", 0)
        ),
        "post_boolean_polybevel_merged_corner_count": int(
            post_boolean_polybevel_stats.get("merged_corner_count", 0)
        ),
        "post_boolean_polybevel_accepted": bool(post_boolean_polybevel_stats.get("accepted", False)),
        "face_part_attribution_mode": (
            "primitive_bounds_with_boolean_operands"
            if boolean_succeeded
            else "source_face_parts"
        ),
        "face_part_attribution_count": len(face_parts_out),
        "face_part_attribution_part_count": len(set(face_parts_out)),
        "face_part_cut_attribution_count": len(cut_attributed_primitive_indices),
        "face_operation_attribution_mode": face_operation_source,
        "face_operation_attribution_count": len(face_operation_ids),
        "face_operation_attribution_operation_count": len(set(face_operation_ids)),
        "face_operation_ids": face_operation_ids,
        "face_operation_summary": _face_operation_summary(
            face_operation_ids,
            cut_operation_ids=cut_attributed_operation_ids,
            source=face_operation_source,
            compound_operations=_compound_operation_reports(shape_ir.primitives),
        ),
        "face_operation_cut_attribution_count": len(cut_attributed_operation_ids),
        "face_operation_cut_attribution_operation_count": len(set(cut_attributed_operation_ids)),
        "bevel_seam_group_count": sum(len(primitive.bevel_seam_groups) for primitive in shape_ir.primitives),
        "polybevel_modifier_count": sum(
            1 for primitive in shape_ir.primitives if primitive.v2_polybevel_modifier is not None
        ),
        "hard_edge_group_count": sum(len(primitive.hard_edge_groups) for primitive in shape_ir.primitives),
        "hard_edge_modifier_count": sum(
            1 for primitive in shape_ir.primitives if primitive.v2_mark_hard_edge_modifier is not None
        ),
        "weighted_normals_modifier_count": sum(
            1 for primitive in shape_ir.primitives if primitive.v2_weighted_normals_modifier is not None
        ),
        "polybevel_geometry_count": sum(
            1
            for primitive in shape_ir.primitives
            if primitive.v2_polybevel_modifier is not None
            and primitive.primitive_type in {"box", "subdivision_box"}
        ),
        "selective_polybevel_geometry_count": sum(
            1
            for primitive in shape_ir.primitives
            if primitive.v2_polybevel_modifier is not None
            and primitive.primitive_type in {"box", "subdivision_box"}
            and _polybevel_edge_pairs(primitive) is not None
        ),
        "topology_modifier_count": sum(
            1
            for primitive in shape_ir.primitives
            if _subdivision_levels(primitive) > 0
            or _remesh_target_edge_length(primitive) is not None
        ),
        "subdivision_modifier_count": sum(
            1 for primitive in shape_ir.primitives if _subdivision_levels(primitive) > 0
        ),
        "remesh_modifier_count": sum(
            1
            for primitive in shape_ir.primitives
            if _remesh_target_edge_length(primitive) is not None
        ),
        "remesh_adaptive_count": sum(
            1
            for primitive in shape_ir.primitives
            if _remesh_target_edge_length(primitive) is not None
            and _remesh_mode(primitive) == "adaptive"
        ),
        "remesh_uniform_count": sum(
            1
            for primitive in shape_ir.primitives
            if _remesh_target_edge_length(primitive) is not None
            and _remesh_mode(primitive) == "uniform"
        ),
        "remesh_smooth_count": sum(
            1
            for primitive in shape_ir.primitives
            if _remesh_target_edge_length(primitive) is not None
            and _remesh_mode(primitive) == "smooth"
        ),
        "remesh_feature_preserving_count": sum(
            1
            for primitive in shape_ir.primitives
            if _remesh_target_edge_length(primitive) is not None
            and _remesh_mode(primitive) == "feature_preserving"
        ),
        "triangle_count": len(combined.faces),
        "vertex_count": len(combined.vertices),
    }
    if post_boolean_polybevel_stats.get("rejected_reason"):
        report["post_boolean_polybevel_rejected_reason"] = str(
            post_boolean_polybevel_stats["rejected_reason"]
        )
    if post_boolean_polybevel_stats.get("fallback_method"):
        report["post_boolean_polybevel_fallback_method"] = str(
            post_boolean_polybevel_stats["fallback_method"]
        )
    if post_boolean_polybevel_stats.get("actual_method"):
        report["post_boolean_polybevel_actual_method"] = str(
            post_boolean_polybevel_stats["actual_method"]
        )
    if post_boolean_polybevel_stats.get("edge_loop_cutback_rejected_reason"):
        report["post_boolean_polybevel_edge_loop_cutback_rejected_reason"] = str(
            post_boolean_polybevel_stats["edge_loop_cutback_rejected_reason"]
        )
    if post_boolean_polybevel_stats.get("edge_loop_cutback_skipped_reason"):
        report["post_boolean_polybevel_edge_loop_cutback_skipped_reason"] = str(
            post_boolean_polybevel_stats["edge_loop_cutback_skipped_reason"]
        )
    if post_boolean_polybevel_stats.get("edge_loop_cutback_edge_limit"):
        report["post_boolean_polybevel_edge_loop_cutback_edge_limit"] = int(
            post_boolean_polybevel_stats["edge_loop_cutback_edge_limit"]
        )
    if post_boolean_polybevel_stats.get("edge_loop_cutback_requested_edge_count"):
        report["post_boolean_polybevel_edge_loop_cutback_requested_edge_count"] = int(
            post_boolean_polybevel_stats["edge_loop_cutback_requested_edge_count"]
        )
    if post_boolean_polybevel_stats.get("visible_seam_strip_boolean_union_failure_reason"):
        report["post_boolean_polybevel_visible_seam_strip_boolean_union_failure_reason"] = str(
            post_boolean_polybevel_stats["visible_seam_strip_boolean_union_failure_reason"]
        )
    if post_boolean_polybevel_stats.get("visible_seam_strip_boolean_union_skipped_reason"):
        report["post_boolean_polybevel_visible_seam_strip_boolean_union_skipped_reason"] = str(
            post_boolean_polybevel_stats["visible_seam_strip_boolean_union_skipped_reason"]
        )
    if "fallback_accepted" in post_boolean_polybevel_stats:
        report["post_boolean_polybevel_fallback_accepted"] = bool(
            post_boolean_polybevel_stats.get("fallback_accepted")
        )
    if "visible_fallback_applied" in post_boolean_polybevel_stats:
        report["post_boolean_polybevel_visible_fallback_applied"] = bool(
            post_boolean_polybevel_stats.get("visible_fallback_applied")
        )
    if post_boolean_polybevel_stats.get("repair_method"):
        report["post_boolean_polybevel_repair_method"] = str(
            post_boolean_polybevel_stats["repair_method"]
        )
    for key in (
        "attempted_group_count",
        "attempted_edge_count",
        "attempted_face_count",
        "attempted_bevel_face_count",
        "attempted_strip_count",
        "source_boundary_edge_count",
        "candidate_boundary_edge_count",
        "source_nonmanifold_edge_count",
        "candidate_nonmanifold_edge_count",
        "source_body_count",
        "candidate_body_count",
        "fallback_face_count",
        "fallback_vertex_count",
        "fallback_boundary_edge_count",
        "fallback_nonmanifold_edge_count",
        "fallback_body_count",
        "visible_seam_strip_face_count",
        "visible_seam_strip_body_count_delta",
        "visible_seam_strip_limit",
        "visible_seam_strip_skipped_edge_count",
        "adaptive_surface_face_count",
        "adaptive_surface_vertex_count",
        "adaptive_surface_body_count",
        "adaptive_surface_boundary_edge_count",
        "adaptive_surface_nonmanifold_edge_count",
    ):
        if key in post_boolean_polybevel_stats:
            report[f"post_boolean_polybevel_{key}"] = int(post_boolean_polybevel_stats.get(key, 0))
    for key in (
        "source_watertight",
        "candidate_watertight",
        "fallback_watertight",
        "adaptive_surface_watertight",
        "edge_loop_cutback_attempted",
        "edge_loop_cutback_accepted",
        "visible_seam_strip_boolean_union_attempted",
        "visible_seam_strip_boolean_union_succeeded",
        "visible_seam_strip_truncated",
    ):
        if key in post_boolean_polybevel_stats:
            report[f"post_boolean_polybevel_{key}"] = bool(post_boolean_polybevel_stats.get(key, False))
    report.update(boolean_details)
    if post_boolean_seam_groups:
        report["post_boolean_seam_groups"] = _public_post_boolean_seam_groups(post_boolean_seam_groups)
    if post_boolean_polybevel_stats.get("strip_records"):
        report["post_boolean_polybevel_strips"] = [
            dict(record) for record in post_boolean_polybevel_stats.get("strip_records", [])
        ]
    if boolean_fallback_reason is not None:
        report["boolean_fallback_reason"] = boolean_fallback_reason
    return combined, face_parts_out, report


def _primitive_bounds(primitive: ShapePrimitive, margin: float) -> tuple[np.ndarray, np.ndarray]:
    center = np.asarray(primitive.center, dtype=np.float64)
    if primitive.primitive_type == "box":
        if primitive.extents is None:
            raise _missing_box_extents_error(primitive)
        half = np.asarray(primitive.extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "cylinder":
        if primitive.radius is None or primitive.height is None:
            raise _missing_cylinder_dimensions_error(primitive)
        radius = float(primitive.radius) + margin
        half_height = float(primitive.height) / 2.0 + margin
        if primitive.axis == "x":
            half = np.asarray([half_height, radius, radius], dtype=np.float64)
        elif primitive.axis == "z":
            half = np.asarray([radius, radius, half_height], dtype=np.float64)
        else:
            half = np.asarray([radius, half_height, radius], dtype=np.float64)
    elif primitive.primitive_type == "sphere":
        if primitive.radius is None:
            raise _missing_sphere_radius_error(primitive)
        radius = float(primitive.radius) + margin
        half = np.asarray([radius, radius, radius], dtype=np.float64)
    elif primitive.primitive_type == "capsule":
        if primitive.radius is None or primitive.length is None:
            raise _missing_capsule_dimensions_error(primitive)
        radius = float(primitive.radius) + margin
        half_height = float(primitive.length) * 0.5 + margin
        if primitive.axis == "x":
            half = np.asarray([half_height, radius, radius], dtype=np.float64)
        elif primitive.axis == "z":
            half = np.asarray([radius, radius, half_height], dtype=np.float64)
        else:
            half = np.asarray([radius, half_height, radius], dtype=np.float64)
    elif primitive.primitive_type == "revolved_profile":
        radius, height = _revolved_profile_extents(primitive)
        radius = radius + margin
        half_height = height / 2.0 + margin
        if primitive.axis == "x":
            half = np.asarray([half_height, radius, radius], dtype=np.float64)
        elif primitive.axis == "z":
            half = np.asarray([radius, radius, half_height], dtype=np.float64)
        else:
            half = np.asarray([radius, half_height, radius], dtype=np.float64)
    elif primitive.primitive_type == "extruded_profile":
        # AABB derived from the polygon's 2D bbox (in the cross-section
        # plane) plus the extrude_height along ``axis``.
        umin, umax, vmin, vmax = _extruded_profile_polygon_bbox(primitive)
        if primitive.extrude_height is None or float(primitive.extrude_height) <= 0.0:
            raise _missing_extruded_profile_height_error(primitive)
        half_axial = float(primitive.extrude_height) / 2.0 + margin
        half_u = (umax - umin) / 2.0 + margin
        half_v = (vmax - vmin) / 2.0 + margin
        if primitive.axis == "x":
            half = np.asarray([half_axial, half_v, half_u], dtype=np.float64)
        elif primitive.axis == "z":
            half = np.asarray([half_u, half_v, half_axial], dtype=np.float64)
        else:
            half = np.asarray([half_u, half_axial, half_v], dtype=np.float64)
    elif primitive.primitive_type == "rounded_slot":
        return _primitive_bounds(_rounded_slot_as_extruded_profile_primitive(primitive), margin)
    elif primitive.primitive_type == "socket":
        return _primitive_bounds(_socket_as_exact_primitive(primitive), margin)
    elif primitive.primitive_type == "weld_seam":
        return _primitive_bounds(_weld_seam_as_exact_primitive(primitive), margin)
    elif primitive.primitive_type == "dent_mask_set":
        bmin, bmax = _dent_mask_set_bounds(primitive)
        half = (bmax - bmin) * 0.5 + margin
        center = (bmin + bmax) * 0.5
        return center - half, center + half
    elif primitive.primitive_type == "edge_chip_set":
        bmin, bmax = _edge_chip_set_bounds(primitive)
        half = (bmax - bmin) * 0.5 + margin
        center = (bmin + bmax) * 0.5
        return center - half, center + half
    elif primitive.primitive_type == "surface_patch_set":
        bmin, bmax = _surface_patch_set_bounds(primitive)
        half = (bmax - bmin) * 0.5 + margin
        center = (bmin + bmax) * 0.5
        return center - half, center + half
    elif primitive.primitive_type == "hinge":
        bmin, bmax = _hinge_bounds(primitive)
        half = (bmax - bmin) * 0.5 + margin
        center = (bmin + bmax) * 0.5
        return center - half, center + half
    elif primitive.primitive_type == "handle":
        bmin, bmax = _handle_bounds(primitive)
        half = (bmax - bmin) * 0.5 + margin
        center = (bmin + bmax) * 0.5
        return center - half, center + half
    elif primitive.primitive_type == "countersunk_hole":
        return _primitive_bounds(_countersunk_hole_as_revolved_profile_primitive(primitive), margin)
    elif primitive.primitive_type == "countersunk_hole_set":
        bmin, bmax = _countersunk_hole_set_bounds(primitive)
        half = (bmax - bmin) * 0.5 + margin
        center = (bmin + bmax) * 0.5
        return center - half, center + half
    elif primitive.primitive_type == "panel":
        return _primitive_bounds(_panel_as_extruded_profile_primitive(primitive), margin)
    elif primitive.primitive_type == "panel_frame":
        if (
            primitive.width is None
            or primitive.height is None
            or primitive.border_width is None
            or primitive.thickness is None
        ):
            raise _missing_panel_frame_dimensions_error(primitive)
        axis = str(primitive.normal_axis or primitive.axis)
        width_axis, height_axis = _tangent_axis_pair(axis)
        width_axis = str(primitive.width_axis or width_axis)
        height_axis = str(primitive.height_axis or height_axis)
        extents = _axis_mapped_extents(
            length_axis=width_axis,
            width_axis=height_axis,
            normal_axis=axis,
            length=float(primitive.width),
            width=float(primitive.height),
            height=float(primitive.thickness),
        )
        half = np.asarray(extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "panel_line_cut":
        return _primitive_bounds(_panel_line_cut_as_exact_primitive(primitive), margin)
    elif primitive.primitive_type == "inset_cut":
        return _primitive_bounds(_inset_cut_as_box_primitive(primitive), margin)
    elif primitive.primitive_type == "perforated_panel":
        if primitive.width is None or primitive.height is None or primitive.thickness is None:
            raise _missing_perforated_panel_dimensions_error(primitive)
        column_axis, row_axis = _tangent_axis_pair(primitive.axis)
        column_axis = str(primitive.column_axis or column_axis)
        row_axis = str(primitive.row_axis or row_axis)
        extents = _axis_mapped_extents(
            length_axis=column_axis,
            width_axis=row_axis,
            normal_axis=primitive.axis,
            length=float(primitive.width),
            width=float(primitive.height),
            height=float(primitive.thickness),
        )
        half = np.asarray(extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "fastener_grid":
        bounds_min, bounds_max = _fastener_grid_bounds(primitive)
        center = (bounds_min + bounds_max) * 0.5
        half = 0.5 * np.maximum(bounds_max - bounds_min, NUMERIC_EPSILON) + margin
    elif primitive.primitive_type == "corner_guard_set":
        bounds_min, bounds_max = _corner_guard_set_bounds(primitive)
        center = (bounds_min + bounds_max) * 0.5
        half = 0.5 * np.maximum(bounds_max - bounds_min, NUMERIC_EPSILON) + margin
    elif primitive.primitive_type == "ribbed_panel":
        if primitive.width is None or primitive.height is None or primitive.thickness is None:
            raise _missing_ribbed_panel_dimensions_error(primitive)
        width_axis, height_axis = _tangent_axis_pair(primitive.axis)
        width_axis = str(primitive.width_axis or width_axis)
        height_axis = str(primitive.height_axis or height_axis)
        rib_height = float(primitive.rib_height or max(float(primitive.thickness) * 0.65, 0.12))
        extents = _axis_mapped_extents(
            length_axis=width_axis,
            width_axis=height_axis,
            normal_axis=primitive.axis,
            length=float(primitive.width),
            width=float(primitive.height),
            height=float(primitive.thickness) + rib_height,
        )
        half = np.asarray(extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "structural_beam":
        return _primitive_bounds(_structural_beam_as_extruded_profile_primitive(primitive), margin)
    elif primitive.primitive_type == "rail":
        return _primitive_bounds(_rail_as_extruded_profile_primitive(primitive), margin)
    elif primitive.primitive_type == "louver_panel":
        if primitive.width is None or primitive.height is None or primitive.thickness is None:
            raise _missing_louver_panel_dimensions_error(primitive)
        width_axis, height_axis = _tangent_axis_pair(primitive.axis)
        width_axis = str(primitive.width_axis or width_axis)
        height_axis = str(primitive.height_axis or height_axis)
        extents = _axis_mapped_extents(
            length_axis=width_axis,
            width_axis=height_axis,
            normal_axis=primitive.axis,
            length=float(primitive.width),
            width=float(primitive.height),
            height=float(primitive.thickness) + float(primitive.slat_depth or 0.0),
        )
        half = np.asarray(extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "vent_slats":
        bmin, bmax = _vent_slats_bounds(primitive)
        center = (bmin + bmax) * 0.5
        half = 0.5 * np.maximum(bmax - bmin, NUMERIC_EPSILON) + margin
    elif primitive.primitive_type == "component_assembly":
        bmin, bmax = _component_assembly_bounds(primitive)
        center = (bmin + bmax) * 0.5
        half = 0.5 * np.maximum(bmax - bmin, NUMERIC_EPSILON) + margin
    elif primitive.primitive_type == "ladder_frame":
        if primitive.length is None or primitive.width is None or primitive.rail_radius is None:
            raise _missing_ladder_frame_dimensions_error(primitive)
        length_axis = str(primitive.length_axis or "y")
        width_axis = str(primitive.width_axis or "x")
        remaining_axis = next(axis for axis in ("x", "y", "z") if axis not in {length_axis, width_axis})
        radius = max(float(primitive.rail_radius), float(primitive.rung_radius or 0.0))
        extents = _axis_mapped_extents(
            length_axis=length_axis,
            width_axis=width_axis,
            normal_axis=remaining_axis,
            length=float(primitive.length) + radius * 2.0,
            width=float(primitive.width) + radius * 2.0,
            height=radius * 2.0,
        )
        half = np.asarray(extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "truss_frame":
        if primitive.length is None or primitive.height is None or primitive.member_radius is None:
            raise _missing_truss_frame_dimensions_error(primitive)
        length_axis = str(primitive.length_axis or "y")
        height_axis = str(primitive.height_axis or "z")
        depth_axis = str(primitive.depth_axis or "x")
        radius = float(primitive.member_radius)
        extents = _axis_mapped_extents(
            length_axis=length_axis,
            width_axis=height_axis,
            normal_axis=depth_axis,
            length=float(primitive.length) + radius * 2.0,
            width=float(primitive.height) + radius * 2.0,
            height=max(float(primitive.depth or 0.0), radius * 2.0) + radius * 2.0,
        )
        half = np.asarray(extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "support_bracket":
        if primitive.width is None or primitive.height is None or primitive.depth is None:
            raise _missing_support_bracket_dimensions_error(primitive)
        normal_axis = str(primitive.normal_axis or primitive.axis or "z")
        width_axis, height_axis = _tangent_axis_pair(normal_axis)
        width_axis = str(primitive.width_axis or width_axis)
        height_axis = str(primitive.height_axis or height_axis)
        extents = _axis_mapped_extents(
            length_axis=width_axis,
            width_axis=height_axis,
            normal_axis=normal_axis,
            length=float(primitive.width),
            width=float(primitive.height),
            height=float(primitive.depth),
        )
        half = np.asarray(extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "trim_band":
        if primitive.length is None or primitive.width is None or primitive.thickness is None:
            raise _missing_trim_band_dimensions_error(primitive)
        axis = primitive.axis
        length_axis, width_axis = _tangent_axis_pair(axis)
        length_axis = str(primitive.length_axis or length_axis)
        width_axis = str(primitive.width_axis or width_axis)
        extents = _axis_mapped_extents(
            length_axis=length_axis,
            width_axis=width_axis,
            normal_axis=axis,
            length=float(primitive.length),
            width=float(primitive.width),
            height=float(primitive.thickness),
        )
        half = np.asarray(extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "torus":
        if primitive.major_radius is None or primitive.minor_radius is None:
            raise _missing_torus_dimensions_error(primitive)
        major = float(primitive.major_radius)
        minor = float(primitive.minor_radius)
        # Outer ring radius is major+minor; tube thickness along the
        # ring axis is 2*minor. Same axis-remap layout as cylinder.
        radius = major + minor + margin
        half_height = minor + margin
        if primitive.axis == "x":
            half = np.asarray([half_height, radius, radius], dtype=np.float64)
        elif primitive.axis == "z":
            half = np.asarray([radius, radius, half_height], dtype=np.float64)
        else:
            half = np.asarray([radius, half_height, radius], dtype=np.float64)
    elif primitive.primitive_type == "tube":
        if primitive.outer_radius is None or primitive.height is None:
            raise _missing_tube_dimensions_error(primitive)
        radius = float(primitive.outer_radius) + margin
        half_height = float(primitive.height) * 0.5 + margin
        if primitive.axis == "x":
            half = np.asarray([half_height, radius, radius], dtype=np.float64)
        elif primitive.axis == "z":
            half = np.asarray([radius, radius, half_height], dtype=np.float64)
        else:
            half = np.asarray([radius, half_height, radius], dtype=np.float64)
    elif primitive.primitive_type == "gear":
        radius = _gear_outer_radius(primitive) + margin
        half_height = float(primitive.thickness or 0.0) * 0.5 + margin
        if primitive.axis == "x":
            half = np.asarray([half_height, radius, radius], dtype=np.float64)
        elif primitive.axis == "z":
            half = np.asarray([radius, radius, half_height], dtype=np.float64)
        else:
            half = np.asarray([radius, half_height, radius], dtype=np.float64)
    elif primitive.primitive_type == "flange":
        if primitive.outer_radius is None or primitive.thickness is None:
            raise _missing_flange_dimensions_error(primitive)
        radius = float(primitive.outer_radius) + margin
        half_height = float(primitive.thickness) / 2.0 + margin
        if primitive.axis == "x":
            half = np.asarray([half_height, radius, radius], dtype=np.float64)
        elif primitive.axis == "z":
            half = np.asarray([radius, radius, half_height], dtype=np.float64)
        else:
            half = np.asarray([radius, half_height, radius], dtype=np.float64)
    elif primitive.primitive_type == "subdivision_box":
        # Per-corner radii are clamped to fit within ``extents``, so the
        # box envelope is unchanged regardless of corner_radii values.
        if primitive.extents is None:
            raise _missing_subdivision_box_extents_error(primitive)
        half = np.asarray(primitive.extents, dtype=np.float64) / 2.0 + margin
    elif primitive.primitive_type == "swept_profile":
        # AABB of the path expanded by the cross-section circumradius.
        # The path origin offset means the primitive's ``center`` already
        # acts as the global anchor — re-derive the axis-aligned envelope
        # from the path itself, ignoring the precomputed ``center``.
        path_min, path_max, circumradius = _swept_profile_extents(primitive)
        reach = circumradius + margin
        center = np.asarray(primitive.center, dtype=np.float64) + 0.5 * (path_min + path_max)
        half = 0.5 * (path_max - path_min) + reach
    elif primitive.primitive_type == "helical_sweep":
        return _primitive_bounds(_helical_sweep_as_swept_profile_primitive(primitive), margin)
    elif primitive.primitive_type == "spring":
        return _primitive_bounds(
            _helical_sweep_as_swept_profile_primitive(_spring_as_helical_sweep_primitive(primitive)),
            margin,
        )
    elif primitive.primitive_type == "threaded_cylinder":
        if primitive.radius is None or primitive.height is None or primitive.thread_depth is None:
            raise _missing_threaded_cylinder_dimensions_error(primitive)
        radius = float(primitive.radius) + float(primitive.thread_depth) + margin
        half_height = float(primitive.height) / 2.0 + margin
        if primitive.axis == "x":
            half = np.asarray([half_height, radius, radius], dtype=np.float64)
        elif primitive.axis == "z":
            half = np.asarray([radius, radius, half_height], dtype=np.float64)
        else:
            half = np.asarray([radius, half_height, radius], dtype=np.float64)
    elif primitive.primitive_type == "curved_tube":
        return _primitive_bounds(_curved_tube_as_swept_profile_primitive(primitive), margin)
    elif primitive.primitive_type == "lofted_solid":
        # Same envelope strategy as swept_profile: section-centers AABB
        # expanded by the worst-case cross-section reach across all
        # rings. The exact mesh path produces the actual ring-stitched
        # geometry; this AABB is only a safe outer bound for the
        # candidate-primitive sweep.
        path_min, path_max, circumradius = _lofted_solid_extents(primitive)
        reach = circumradius + margin
        center = np.asarray(primitive.center, dtype=np.float64) + 0.5 * (path_min + path_max)
        half = 0.5 * (path_max - path_min) + reach
    elif primitive.primitive_type in {"heightfield", "terrain_patch"}:
        # Heightfield AABB is the lifted lattice's bounding box; the
        # primitive's ``center`` shifts the whole grid in world space.
        _, _, heights, (xmin, ymin, xmax, ymax), vertical_scale = (
            _validate_heightfield_inputs(primitive)
        )
        z_min = float(np.min(heights)) * vertical_scale
        z_max = float(np.max(heights)) * vertical_scale
        center = np.asarray(primitive.center, dtype=np.float64) + np.asarray(
            [
                0.5 * (xmin + xmax),
                0.5 * (ymin + ymax),
                0.5 * (z_min + z_max),
            ],
            dtype=np.float64,
        )
        half = (
            np.asarray(
                [
                    0.5 * (xmax - xmin),
                    0.5 * (ymax - ymin),
                    0.5 * max(z_max - z_min, NUMERIC_EPSILON),
                ],
                dtype=np.float64,
            )
            + margin
        )
    elif (
        primitive.primitive_type == "sdf_metaball_cluster"
        and not (primitive.mesh_vertices and primitive.mesh_faces)
    ):
        v2_metadata = _v2_semantic_metadata(primitive)
        modifier = v2_metadata.get("v2_sdf_metaball_cluster_modifier")
        modifier = modifier if isinstance(modifier, dict) else {}
        return _sdf_metaball_cluster_modifier_bounds(primitive, modifier, margin)
    elif primitive.primitive_type in _SEMANTIC_MESH_BACKED_PRIMITIVE_TYPES:
        # AABB derived directly from the extracted vertices (already in
        # mesh-local cm); ``center`` shifts the whole bag in world space.
        vertices, _ = _sdf_mesh_arrays(primitive)
        vmin = vertices.min(axis=0)
        vmax = vertices.max(axis=0)
        center = np.asarray(primitive.center, dtype=np.float64) + 0.5 * (vmin + vmax)
        half = 0.5 * np.maximum(vmax - vmin, NUMERIC_EPSILON) + margin
    else:
        raise _unsupported_primitive_type_error(primitive.primitive_type)
    return center - half, center + half


def _iter_candidate_primitives(
    shape_ir: ShapeIR, margin: float
) -> Iterable[tuple[ShapePrimitive, np.ndarray, np.ndarray]]:
    for primitive in shape_ir.primitives:
        bounds_min, bounds_max = _primitive_bounds(primitive, margin)
        yield primitive, bounds_min, bounds_max


def exactify_surface_mesh(
    mesh: trimesh.Trimesh, shape_ir: ShapeIR, fidelity: FidelityProfile
) -> tuple[trimesh.Trimesh, dict[str, float | int]]:
    """Snap a mesh toward the exact primitive surfaces described by ShapeIR."""
    refined = mesh.copy()
    if len(refined.vertices) == 0 or len(shape_ir.primitives) == 0:
        return refined, {"projection_iterations": 0, "mean_vertex_shift": 0.0, "max_vertex_shift": 0.0}

    if fidelity.tier == "cinematic":
        snap_factor, blend, iterations, taubin_iters = 0.034, 0.84, 3, 5
    elif fidelity.tier == "hero":
        snap_factor, blend, iterations, taubin_iters = 0.030, 0.78, 2, 4
    else:
        snap_factor, blend, iterations, taubin_iters = 0.022, 0.62, 1, 2
    snap_radius = max(1.5, float(np.linalg.norm(refined.extents)) * snap_factor)
    margin = snap_radius * 0.8

    with suppress(ValueError, RuntimeError, AttributeError, IndexError):
        trimesh.smoothing.filter_taubin(
            refined, lamb=0.35, nu=-0.37, iterations=taubin_iters
        )

    vertices = np.asarray(refined.vertices, dtype=np.float64)
    shifts: list[float] = []
    primitive_bounds = list(_iter_candidate_primitives(shape_ir, margin))
    for _ in range(iterations):
        updated = vertices.copy()
        for index, vertex in enumerate(vertices):
            best_point: np.ndarray | None = None
            best_distance = snap_radius
            for primitive, bounds_min, bounds_max in primitive_bounds:
                if np.any(vertex < bounds_min) or np.any(vertex > bounds_max):
                    continue
                candidate = _primitive_surface_point(vertex, primitive)
                distance = float(np.linalg.norm(vertex - candidate))
                if distance < best_distance:
                    best_distance = distance
                    best_point = candidate
            if best_point is None:
                continue
            snapped = vertex * (1.0 - blend) + best_point * blend
            updated[index] = snapped
            shifts.append(float(np.linalg.norm(snapped - vertex)))
        vertices = updated

    refined.vertices = vertices
    refined.remove_infinite_values()
    refined.remove_unreferenced_vertices()
    refined.merge_vertices()
    with suppress(ValueError, RuntimeError, AttributeError, IndexError):
        refined.process(validate=True)
    refined.fix_normals()
    return refined, {
        "projection_iterations": iterations,
        "snap_radius": round(float(snap_radius), 6),
        "mean_vertex_shift": round(float(np.mean(shifts)) if shifts else 0.0, 6),
        "max_vertex_shift": round(float(np.max(shifts)) if shifts else 0.0, 6),
    }
